begin;
create temp table _truoc as select count(*) n from public.question_bank;
insert into public.question_bank (subject_code, grade, topic_id, topic_name, form, qtype, difficulty, difficulty_source, question, content_hash, archived, note)
select 'vat-ly', '10', v.tid, v.tname, 'bai_tap', v.q->>'type', v.q->>'difficulty', 'ai', v.q, public.question_content_hash(v.q), true, 'nap-vl10-c4-20261020'
from (values ($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Đơn vị công là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Công được tính bằng $A = F \\cdot s \\cdot \\cos\\alpha$, trong đó $F$ có đơn vị niutơn (N), $s$ có đơn vị mét (m).</p><p class=\"text-base leading-relaxed my-2\">Vì $1\\,\\text{N} = 1\\,\\text{kg}\\cdot\\text{m/s}^2$ nên:</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$1\\,\\text{N}\\cdot\\text{m} = 1\\,\\text{kg}\\cdot\\text{m/s}^2 \\cdot \\text{m} = 1\\,\\text{kg}\\cdot\\text{m}^2/\\text{s}^2$</p><p class=\"text-base leading-relaxed my-2\">Đơn vị này được gọi là jun (J), đơn vị SI của công.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đơn vị công là $\\text{kg}\\cdot\\text{m}^2/\\text{s}^2$, đáp án A.</p>","options":["kg.m$$^{{2}$/s$}${2}$.","W/s.","k.J.","kg.s$$^{{2}$/m$}${2}$."],"answer":0}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Ki lô óat giờ là đơn vị của</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Kilôoát giờ (kW·h) là đơn vị đo công (năng lượng), tức là đơn vị của công cơ học.</p><p class=\"text-base leading-relaxed my-2\">Ta có công thức $A = P \\cdot t$, với $P$ là công suất (đơn vị W) và $t$ là thời gian (đơn vị h). Khi đó đơn vị của $A$ là $\\text{kW} \\cdot \\text{h}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $1\\ \\text{kW·h} = 1000\\ \\text{W} \\cdot 3600\\ \\text{s} = 3{,}6 \\cdot 10^6\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Loại các đáp án còn lại: hiệu suất không có đơn vị; công suất có đơn vị W; động lượng có đơn vị kg·m/s.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án <b>D</b>.</p>","options":["hiệu suất.","công suất.","động lượng.","công cơ học."],"answer":3}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây là <strong>đúng</strong>?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của một lực được tính theo công thức $A = F\\cdot s\\cdot\\cos\\alpha$, trong đó $\\alpha$ là góc giữa lực $\\vec{F}$ và độ dời $\\vec{s}$.</p><p class=\"text-base leading-relaxed my-2\">Công là đại lượng vô hướng, có thể dương, âm hoặc bằng 0 tùy theo giá trị của $\\cos\\alpha$. Đây là giá trị đại số.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Sai. Lực là đại lượng véc tơ nhưng công là đại lượng vô hướng.</p><p class=\"text-base leading-relaxed my-2\">B. Sai. Trong chuyển động tròn đều, lực hướng tâm luôn vuông góc với vận tốc (và độ dời), nên $\\alpha = 90^\\circ$ và $A = 0$.</p><p class=\"text-base leading-relaxed my-2\">C. Đúng. Công là đại lượng vô hướng, có giá trị đại số.</p><p class=\"text-base leading-relaxed my-2\">D. Sai. Vật chuyển động thẳng đều có hợp lực bằng 0, nên công của hợp lực bằng $0$ dù vật có độ dời.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: phát biểu đúng là C.</p>","options":["Lực là đại lượng véc tơ nên công cũng là đại lượng véctơ.","Trong chuyển động tròn, lực hướng tâm thực hiện công vì có cả hai yếu tố lực và độ dời của vật.","Công của lực là đại lượng vô hướng và có giá trị đại số.","Một vật chuyển động thẳng đều, công của hợp lực là khác không vì có độ dời của vật."],"answer":2}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một vật thực hiện công khi</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Công cơ học được thực hiện khi có lực tác dụng lên vật và vật chuyển dời. Công được tính theo công thức $A = F s \\cos\\alpha$, trong đó $\\alpha$ là góc giữa lực và phương chuyển động.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Nếu giá của lực vuông góc với phương chuyển động thì $\\alpha = 90^\\circ$, suy ra $\\cos\\alpha = 0$ và $A = 0$. Loại.</p><p class=\"text-base leading-relaxed my-2\">B. Giá của lực song song với phương chuyển động chỉ là điều kiện để công có độ lớn lớn nhất (khi $\\alpha = 0^\\circ$ hoặc $180^\\circ$). Đây không phải điều kiện cần và đủ để vật thực hiện công. Loại.</p><p class=\"text-base leading-relaxed my-2\">C. Lực làm vật biến dạng không nói đến sự chuyển dời của vật, nên không đủ điều kiện sinh công cơ học. Loại.</p><p class=\"text-base leading-relaxed my-2\">D. Lực tác dụng lên vật làm vật chuyển dời là điều kiện có công cơ học. Chọn.</p><p class=\"text-base leading-relaxed my-2\"><b>Kết luận:</b> đáp án D.</p>","options":["giá của lực vuông góc với phương chuyển động.","giá của lực song song với phương chuyển động.","lực đó làm vật biến dạng.","lực đó tác dụng lên một vật làm vật đó chuyển dời."],"answer":3}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Lực F tác dụng vào một vật không sinh công khi</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực không đổi được tính theo công thức: $A = F\\cdot s\\cdot\\cos\\alpha$, trong đó $\\alpha$ là góc giữa hướng của lực $\\vec{F}$ và hướng chuyển động của vật.</p><p class=\"text-base leading-relaxed my-2\">Lực không sinh công khi $A = 0$, tức là $\\cos\\alpha = 0$ (với $F \\neq 0$ và $s \\neq 0$).</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\alpha = 90^{\\circ}$, nghĩa là lực vuông góc với hướng chuyển động của vật.</p><p class=\"text-base leading-relaxed my-2\">Kiểm tra các phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Cùng hướng chuyển động: $\\alpha = 0^{\\circ}$, $\\cos\\alpha = 1$, công dương (sinh công dương). Loại.</p><p class=\"text-base leading-relaxed my-2\">B. Cản chuyển động: $\\alpha$ lớn, công âm (sinh công cản), không phải bằng 0. Loại.</p><p class=\"text-base leading-relaxed my-2\">C. Góc lớn hơn $90^{\\circ}$: $\\cos\\alpha \\lt 0$, công âm, khác 0. Loại.</p><p class=\"text-base leading-relaxed my-2\">D. Vuông góc với chuyển động: $\\alpha = 90^{\\circ}$, $\\cos\\alpha = 0$, nên $A = 0$. Chọn.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: lực không sinh công khi vuông góc với chuyển động của vật (đáp án D).</p>","options":["cùng hướng chuyển động của vật.","có tác dụng cản chuyển động của vật.","hợp với hướng chuyển động của vật góc lớn hơn 90$^{0}$.","vuông góc với chuyển động của vật."],"answer":3}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">1Wh bằng</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Đơn vị watt-giờ (Wh) là đơn vị đo năng lượng, được tính bằng công suất nhân với thời gian: $A = P \\cdot t$.</p><p class=\"text-base leading-relaxed my-2\">Với $P = 1\\ \\text{W}$ và $t = 1\\ \\text{h} = 3600\\ \\text{s}$:</p><p class=\"text-base leading-relaxed my-2\">$A = 1\\ \\text{W} \\cdot 3600\\ \\text{s} = 3600\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: $1\\ \\text{Wh} = 3600\\ \\text{J}$, chọn đáp án A.</p>","options":["3600 J.","1000 J.","60 J.","1 CV."],"answer":0}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Chọn câu <strong>sai</strong>. Công của lực</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực là đại lượng vô hướng, có giá trị đại số: công có thể dương, âm hoặc bằng không tùy theo góc giữa lực và độ dời.</p><p class=\"text-base leading-relaxed my-2\">Công của lực không đổi tác dụng lên vật có độ dời $\\vec{s}$ được tính theo công thức:</p><p class=\"text-base leading-relaxed my-2\">$A = F.s.\\cos\\alpha$</p><p class=\"text-base leading-relaxed my-2\">Trong đó $\\alpha$ là góc giữa vectơ lực $\\vec{F}$ và vectơ độ dời $\\vec{s}$.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">- A đúng: công là đại lượng vô hướng.</p><p class=\"text-base leading-relaxed my-2\">- B đúng: công có giá trị đại số.</p><p class=\"text-base leading-relaxed my-2\">- C đúng: $A = F.s.\\cos\\alpha$ (với $F$ là lực tác dụng).</p><p class=\"text-base leading-relaxed my-2\">- D sai: vì $\\cos\\alpha$ có thể âm (khi $90^\\circ &lt; \\alpha \\le 180^\\circ$), khi đó công âm. Ví dụ lực ma sát thường sinh công âm.</p><p class=\"text-base leading-relaxed my-2\">Vậy câu sai là D.</p>","options":["là đại lượng vô hướng.","có giá trị đại số.","được tính bằng biểu thức$F_{ms}.s.cosa$.","luôn luôn dương."],"answer":3}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Lực thực hiện công âm khi vật chuyển động trên mặt phẳng nằm ngang là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực được tính theo công thức $A = F\\,s\\cos\\alpha$, trong đó $\\alpha$ là góc giữa vectơ lực và vectơ độ dời.</p><p class=\"text-base leading-relaxed my-2\">Khi vật chuyển động trên mặt phẳng nằm ngang, phân tích từng lực:</p><p class=\"text-base leading-relaxed my-2\">- Trọng lực có phương thẳng đứng, vuông góc với độ dời nằm ngang, nên $\\alpha = 90^\\circ$, $\\cos\\alpha = 0$, suy ra $A = 0$.</p><p class=\"text-base leading-relaxed my-2\">- Lực kéo và lực phát động (cùng chiều chuyển động) có $\\alpha < 90^\\circ$, nên $\\cos\\alpha > 0$, suy ra $A > 0$ (công phát động).</p><p class=\"text-base leading-relaxed my-2\">- Lực ma sát trượt ngược chiều chuyển động nên $\\alpha = 180^\\circ$, $\\cos\\alpha = -1$, suy ra $A = -F_{ms}\\,s < 0$ (công cản).</p><p class=\"text-base leading-relaxed my-2\">Vậy lực thực hiện công âm là lực ma sát. Đáp án đúng: A.</p>","options":["lực ma sát.","lực phát động.","lực kéo.","trọng lực."],"answer":0}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Công của lực tác dụng lên vật bằng không khi góc hợp giữa lực tác dụng và chiều chuyển động là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực được tính theo công thức $A = F \\cdot s \\cdot \\cos\\alpha$, trong đó $F$ là độ lớn lực, $s$ là quãng đường dịch chuyển và $\\alpha$ là góc hợp giữa lực tác dụng và chiều chuyển động.</p><p class=\"text-base leading-relaxed my-2\">Công bằng không khi $A = 0$ với $F \\neq 0$ và $s \\neq 0$, tức là $\\cos\\alpha = 0$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\cos\\alpha = 0$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\alpha = 90^{o}$.</p><p class=\"text-base leading-relaxed my-2\">Kiểm tra các phương án: $\\cos 0^{o} = 1$, $\\cos 60^{o} = 0{,}5$ và $\\cos 180^{o} = -1$ đều khác $0$, nên công không bằng không.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: công của lực bằng không khi góc hợp giữa lực và chiều chuyển động là $90^{o}$.</p>","options":["$0^{o}.$","$60^{o}.$","$180^{o}.$","$90^{o}.$"],"answer":3}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Khi lực $\\overrightarrow{F}$ cùng chiều với độ dịch chuyển $\\overrightarrow{d}$ thì</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực không đổi $\\overrightarrow{F}$ khi điểm đặt chuyển dời một đoạn $\\overrightarrow{d}$ được tính theo công thức: $A = F\\,d\\,\\cos\\alpha$, trong đó $\\alpha$ là góc giữa $\\overrightarrow{F}$ và $\\overrightarrow{d}$.</p><p class=\"text-base leading-relaxed my-2\">Khi $\\overrightarrow{F}$ cùng chiều với $\\overrightarrow{d}$ thì $\\alpha = 0^\\circ$, suy ra $\\cos\\alpha = 1$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A = F\\,d\\cdot 1 = F\\,d$.</p><p class=\"text-base leading-relaxed my-2\">Vì $F>0$ và $d>0$ nên $A>0$. Đáp án đúng là A.</p>","options":["công $A>0.$","công $A<0.$","công $A¹0.$","công $A=0.$"],"answer":0}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Động năng và định lí động năng","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Vật nào sau đây <strong>không có</strong> khả năng sinh công?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Vật có khả năng sinh công khi nó có năng lượng (động năng hoặc thế năng).</p><p class=\"text-base leading-relaxed my-2\">Động năng của vật: $W_d=\\dfrac{1}{2}mv^2$. Vật chuyển động càng nhanh thì khả năng sinh công càng lớn.</p><p class=\"text-base leading-relaxed my-2\">A. Dòng nước lũ đang chảy mạnh có động năng lớn, có thể làm quay tua-bin hoặc cuốn trôi vật cản, nên có khả năng sinh công.</p><p class=\"text-base leading-relaxed my-2\">B. Viên đạn đang bay có vận tốc rất lớn, nên có động năng và có khả năng sinh công (xuyên thủng vật cản).</p><p class=\"text-base leading-relaxed my-2\">C. Búa máy đang rơi có động năng tăng dần khi rơi, có thể đóng cọc, nên có khả năng sinh công.</p><p class=\"text-base leading-relaxed my-2\">D. Hòn đá nằm yên trên mặt đất: vận tốc bằng $0$ nên động năng bằng $0$; độ cao so với mặt đất bằng $0$ nên thế năng trọng trường bằng $0$. Vật không có năng lượng, do đó không có khả năng sinh công.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: chọn phương án D.</p>","options":["Dòng nước lũ đang chảy mạnh.","Viên đạn đang bay.","Búa máy đang rơi.","Hòn đá đang nằm trên mặt đất."],"answer":3}$q$::jsonb, 136, $q$Động năng và định lí động năng$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Công của trọng lực <strong>không có</strong> đặc điểm là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của trọng lực có công thức $A = P\\cdot h = mg(z_1 - z_2)$, với $z_1$, $z_2$ là độ cao đầu và cuối so với mốc (chọn trục $Oz$ hướng lên).</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Sai. Công của trọng lực có thể dương (vật đi xuống, $z_1 \\gt z_2$) hoặc âm (vật đi lên, $z_1 \\lt z_2$). Nên công không luôn dương.</p><p class=\"text-base leading-relaxed my-2\">B. Đúng. Trên mặt phẳng ngang, $z_1 = z_2$ nên $A = 0$.</p><p class=\"text-base leading-relaxed my-2\">C. Đúng. Trọng lực là lực thế; với quỹ đạo khép kín, điểm đầu trùng điểm cuối nên $z_1 = z_2$ và $A = 0$.</p><p class=\"text-base leading-relaxed my-2\">D. Đúng. Công của trọng lực bằng độ giảm thế năng: $A = W_{t1} - W_{t2}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án cần chọn là A.</p>","options":["luôn luôn mang giá trị dương.","bằng không khi vật chuyển động trên mặt phẳng ngang.","bằng không khi quỹ đạo của vật là một đường khép kín.","bằng độ giảm thế năng của vật"],"answer":0}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn và chuyển hoá năng lượng","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hiện tượng nào dưới đây <strong>không</strong> tuân theo định luật bảo toàn năng lượng?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Định luật bảo toàn năng lượng: năng lượng không tự sinh ra cũng không tự mất đi, chỉ chuyển từ dạng này sang dạng khác hoặc truyền từ vật này sang vật khác; tổng năng lượng của một hệ cô lập là không đổi.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Bếp nguội đi khi tắt lửa: nhiệt năng của bếp truyền một phần cho môi trường xung quanh (dưới dạng nhiệt và bức xạ). Năng lượng được bảo toàn.</p><p class=\"text-base leading-relaxed my-2\">B. Xe dừng lại khi tắt máy: động năng của xe chuyển phần lớn thành nhiệt năng do ma sát ở mặt đường, bánh xe và không khí. Năng lượng được bảo toàn.</p><p class=\"text-base leading-relaxed my-2\">C. Bàn là nguội đi khi tắt điện: nhiệt năng của bàn là truyền ra môi trường. Năng lượng được bảo toàn.</p><p class=\"text-base leading-relaxed my-2\">Cả ba hiện tượng đều tuân theo định luật bảo toàn năng lượng, nên không có hiện tượng nào không tuân theo.</p><p class=\"text-base leading-relaxed my-2\">Đáp án: D.</p>","options":["Bếp nguội đi khi tắt lửa.","Xe dừng lại khi tắt máy.","Bàn là nguội đi khi tắt điện.","Không có hiện tượng nào."],"answer":3}$q$::jsonb, 133, $q$Định luật bảo toàn và chuyển hoá năng lượng$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Hao phí năng lượng và cách giảm hao phí","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trong máy điện, điện năng thu được bao giờ cũng có giá trị nhỏ hơn cơ năng cung cấp cho máy vì</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo định luật bảo toàn và chuyển hóa năng lượng, năng lượng không tự sinh ra hay mất đi mà chỉ chuyển từ dạng này sang dạng khác.</p><p class=\"text-base leading-relaxed my-2\">Trong máy điện (máy phát điện), cơ năng cung cấp cho máy được chuyển thành điện năng có ích và một phần chuyển thành các dạng năng lượng khác không mong muốn như nhiệt năng do tỏa nhiệt trên điện trở các cuộn dây, do ma sát ở trục quay và các bộ phận cơ học, do dòng Fu-cô trong lõi sắt.</p><p class=\"text-base leading-relaxed my-2\">Vì vậy điện năng thu được luôn nhỏ hơn cơ năng cung cấp: $W_{\\text{điện}} \\lt W_{\\text{cơ}}$.</p><p class=\"text-base leading-relaxed my-2\">Các phương án còn lại sai: A vì đơn vị không phải lý do; C vì năng lượng không tự biến mất; D vì không có cơ sở so sánh chất lượng như vậy.</p><p class=\"text-base leading-relaxed my-2\">Đáp án đúng: B.</p>","options":["một đơn vị điện năng lớn hơn một đơn vị cơ năng.","một phần cơ năng đã biến thành dạng năng lượng khác ngoài điện năng.","một phần cơ năng đã tự biến mất.","chất lượng điện năng cao hơn chất lượng cơ năng."],"answer":1}$q$::jsonb, 141, $q$Hao phí năng lượng và cách giảm hao phí$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn và chuyển hoá năng lượng","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trong máy phát điện gió, dạng năng lượng nào đã được chuyển hóa thành điện năng?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Máy phát điện gió hoạt động nhờ cánh quạt bị gió làm quay.</p><p class=\"text-base leading-relaxed my-2\">Gió có động năng, làm cánh quạt quay nên sinh ra cơ năng (động năng của chuyển động quay).</p><p class=\"text-base leading-relaxed my-2\">Cơ năng này truyền đến rôto của máy phát và được chuyển thành điện năng nhờ hiện tượng cảm ứng điện từ.</p><p class=\"text-base leading-relaxed my-2\">Vậy trong máy phát điện gió, cơ năng được chuyển hóa thành điện năng.</p>","options":["Cơ năng.","Nhiệt năng.","Hóa năng.","Quang năng."],"answer":0}$q$::jsonb, 133, $q$Định luật bảo toàn và chuyển hoá năng lượng$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn và chuyển hoá năng lượng","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Dòng điện do pin mặt trời cung cấp có gì khác với dòng điện do máy phát điện gió cung cấp?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Pin mặt trời biến đổi trực tiếp quang năng thành điện năng nhờ hiệu ứng quang điện trong, tạo ra suất điện động không đổi chiều, nên cung cấp <strong>dòng điện một chiều</strong>.</p><p class=\"text-base leading-relaxed my-2\">Máy phát điện gió dùng cuộn dây quay trong từ trường (hiện tượng cảm ứng điện từ), suất điện động $e=E_0\\cos(\\omega t+\\varphi)$ đổi chiều tuần hoàn, nên cung cấp <strong>dòng điện xoay chiều</strong>.</p><p class=\"text-base leading-relaxed my-2\">Kiểm tra các phương án: A sai vì công suất không phải là tiêu chí phân biệt bản chất dòng điện; C sai vì cả hai đều cho dòng liên tục; D sai vì đảo ngược đặc điểm của hai loại.</p><p class=\"text-base leading-relaxed my-2\">Đáp án đúng: B.</p>","options":["Pin Mặt Trời có công suất lớn hơn máy phát điện gió.","Dòng điện do pin mặt trời cung cấp là dòng một chiều, còn do máy phát điện gió là xoay chiều.","Pin Mặt Trời cho dòng điện liên tục, còn máy phát điện gió cung cấp dòng điện đứt quãng.","Dòng điện do Pin Mặt Trời cung cấp là dòng điện xoay chiều còn do máy phát điện cung cấp là dòng một chiều biến đổi."],"answer":1}$q$::jsonb, 133, $q$Định luật bảo toàn và chuyển hoá năng lượng$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Đơn vị nào sau đây là đơn vị của công?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Công được tính theo công thức $A = F\\cdot s\\cdot\\cos\\alpha$, với lực $F$ có đơn vị niutơn $(N)$ và quãng đường $s$ có đơn vị mét $(m)$.</p><p class=\"text-base leading-relaxed my-2\">Do đó đơn vị của công là $N\\cdot m$. Vì $1\\,N = 1\\,kg\\cdot m/s^2$ nên $1\\,N\\cdot m = 1\\,kg\\cdot m^2/s^2$ (tức jun, $J$).</p><p class=\"text-base leading-relaxed my-2\">Xét các phương án:</p><p class=\"text-base leading-relaxed my-2\">A. $N/m$ là đơn vị của độ cứng lò xo, không phải công.</p><p class=\"text-base leading-relaxed my-2\">B. $kg\\cdot m^2/s^2$ tương đương $N\\cdot m$, đúng là đơn vị của công.</p><p class=\"text-base leading-relaxed my-2\">C. $N/s$ là đơn vị của tốc độ thay đổi lực, không phải công.</p><p class=\"text-base leading-relaxed my-2\">D. $kg\\cdot m^2/s$ không phải thứ nguyên của công (thiếu bình phương ở đơn vị thời gian).</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đơn vị của công là $kg\\cdot m^2/s^2$, chọn phương án B.</p>","options":["N/m.","kg.m$$^{{2}$/s$}${2}$.","N/s.","kg.m$^{2}$/s."],"answer":1}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trọng lực không thực hiện công khi</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của trọng lực: $A = P \\cdot s \\cdot \\cos\\alpha = mg\\cdot s\\cdot\\cos\\alpha$, trong đó $\\alpha$ là góc giữa phương trọng lực (hướng xuống) và độ dời $\\vec{s}$.</p><p class=\"text-base leading-relaxed my-2\">Trọng lực không thực hiện công khi $\\alpha = 90^\\circ$, tức là độ dời vuông góc với trọng lực, nghĩa là vật chỉ chuyển động theo phương ngang.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Vật rơi tự do: độ dời có thành phần thẳng đứng hướng xuống, $\\alpha = 0^\\circ$, trọng lực sinh công dương. Loại.</p><p class=\"text-base leading-relaxed my-2\">B. Vật chuyển động biến đổi đều trên mặt phẳng ngang: độ dời theo phương ngang, $\\alpha = 90^\\circ$, nên $A = mg\\cdot s\\cdot\\cos 90^\\circ = 0$. Chọn.</p><p class=\"text-base leading-relaxed my-2\">C. Vật trượt trên mặt phẳng nghiêng: độ dời có thành phần thẳng đứng xuống, trọng lực sinh công dương. Loại.</p><p class=\"text-base leading-relaxed my-2\">D. Vật chuyển động ném ngang: vật vẫn rơi xuống nên độ dời có thành phần thẳng đứng hướng xuống, trọng lực sinh công dương. Loại.</p><p class=\"text-base leading-relaxed my-2\"><strong>Kết luận:</strong> Trọng lực không thực hiện công khi vật chuyển động biến đổi đều trên mặt phẳng ngang. Đáp án B.</p>","options":["vật đang rơi tự do.","vật đang chuyển động biến đổi đều trên mặt phẳng ngang.","vật đang trượt trên mặt phẳng nghiêng,","vật đang chuyển động ném ngang."],"answer":1}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Công của lực là công cản trong trường hợp nào sau đây?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực là công cản khi lực có hướng ngược với hướng chuyển động, tức là $A \\lt 0$ (hoặc $\\alpha \\gt 90^\\circ$ với $\\alpha$ là góc giữa lực và độ dời).</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Lực kéo cùng chiều chuyển động, $A = Fs\\cos 0^\\circ \\gt 0$: công phát động.</p><p class=\"text-base leading-relaxed my-2\">B. Vật chuyển động ném ngang đi xuống, trọng lực cùng chiều với độ dời theo phương thẳng đứng, $A \\gt 0$: công phát động.</p><p class=\"text-base leading-relaxed my-2\">C. Vật trượt lên mặt phẳng nghiêng, thành phần trọng lực $P\\sin\\alpha$ hướng xuống dọc mặt nghiêng, ngược chiều chuyển động nên $A = -P\\sin\\alpha \\cdot s \\lt 0$: đây là công cản.</p><p class=\"text-base leading-relaxed my-2\">D. Vật rơi tự do, trọng lực cùng chiều chuyển động, $A \\gt 0$: công phát động.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: công cản xuất hiện khi vật trượt lên mặt phẳng nghiêng, đáp án C.</p>","options":["Công của lực kéo khi ta kéo vật trượt thẳng đều trên mặt phẳng ngang.","Công của trọng lực khi vật đang chuyển động ném ngang.","Công của trọng lực khi vật đang trượt lên trên mặt phẳng nghiêng.","Công của trọng lực khi vật đang rơi tự do."],"answer":2}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Người nào dưới đây đang thực hiện công cơ học?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Điều kiện để có công cơ học: lực tác dụng lên vật phải có thành phần cùng phương với chuyển dời của vật, tức là có lực tác dụng và vật phải dịch chuyển theo phương của lực.</p><p class=\"text-base leading-relaxed my-2\">Công thức: $A = F \\cdot s \\cdot \\cos\\alpha$, với $\\alpha$ là góc giữa lực $\\vec{F}$ và độ dịch chuyển $\\vec{s}$.</p><p class=\"text-base leading-relaxed my-2\">A. Người ngồi đọc báo: không có độ dịch chuyển nên $s = 0$, không sinh công.</p><p class=\"text-base leading-relaxed my-2\">B. Lực sĩ đỡ quả tạ đứng yên: không có độ dịch chuyển nên $s = 0$, không sinh công.</p><p class=\"text-base leading-relaxed my-2\">C. Người đi xe đạp xuống dốc không đạp: người không tác dụng lực kéo hay đẩy theo phương chuyển động; công là do trọng lực thực hiện, không phải do người sinh ra.</p><p class=\"text-base leading-relaxed my-2\">D. Học sinh kéo nước từ giếng lên: lực kéo hướng lên trên, nước dịch chuyển lên trên cùng phương với lực, $\\alpha = 0^\\circ$, $\\cos\\alpha = 1$, nên $A = F \\cdot s > 0$. Đây là trường hợp có công cơ học.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là <strong>D</strong>.</p>","options":["Người ngồi đọc báo.","Người lực sĩ đỡ quả tạ ở tư thế thẳng đứng.","Người đi xe đạp xuống dốc không cần đạp xe.","Người học sinh đang kéo nước từ dưới giếng lên."],"answer":3}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trường hợp nào dưới đây có công cơ học?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Công cơ học được thực hiện khi có lực tác dụng lên vật và vật dịch chuyển theo phương của lực: $A = F\\cdot s\\cdot\\cos\\alpha$, trong đó $\\alpha$ là góc giữa lực và phương dịch chuyển.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Có lực đẩy nhưng xe không chuyển động, tức $s = 0$ nên $A = 0$.</p><p class=\"text-base leading-relaxed my-2\">B. Lực sĩ đứng yên, không có dịch chuyển nên $s = 0$, $A = 0$.</p><p class=\"text-base leading-relaxed my-2\">C. Quả bưởi rơi theo phương thẳng đứng, trọng lực cùng phương và cùng chiều với chuyển động nên $\\alpha = 0$, $\\cos\\alpha = 1$, do đó $A = P\\cdot h > 0$. Đây là công cơ học.</p><p class=\"text-base leading-relaxed my-2\">D. Vật trượt đều trên mặt bàn nhẵn nằm ngang, không có lực ma sát. Lực tác dụng lên vật (trọng lực, phản lực pháp tuyến) đều vuông góc với phương chuyển động nên $\\cos\\alpha = 0$, $A = 0$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: chỉ phương án C có công cơр học.</p>","options":["Hành khách đang ra sức đẩy một xe khách bị chết máy, nhưng xe vẫn không chuyển động được.","Một lực sĩ cử tạ đang đứng yên ở tư thế đỡ quả tạ.","Một quả bưởi rơi từ cành cây xuống.","Một vật sau khi trượt xuống hết một mặt phẳng nghiêng, trượt đều trên mặt bàn nhẵn nằm ngang coi như không có ma sát."],"answer":2}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây là <strong>sai</strong>?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực $\\vec{F}$ thực hiện khi vật dịch chuyển một đoạn $\\vec{s}$ là $A = Fs\\cos\\alpha$, trong đó $\\alpha$ là góc giữa $\\vec{F}$ và $\\vec{s}$.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Đúng. Lực cản có chiều ngược với chuyển động, $\\alpha = 180^\\circ$, nên công của lực cản là công âm (công cản).</p><p class=\"text-base leading-relaxed my-2\">B. Đúng. Nếu $\\alpha = 90^\\circ$ thì $\\cos\\alpha = 0$, suy ra $A = 0$.</p><p class=\"text-base leading-relaxed my-2\">C. Đúng. Trong chuyển động tròn đều, lực hướng tâm luôn vuông góc với vận tốc, nên $A = 0$ ở mọi thời điểm.</p><p class=\"text-base leading-relaxed my-2\">D. Sai. Vật có gia tốc chỉ cần có hợp lực khác không. Hợp lực có thể sinh công âm (khi vật chuyển động chậm dần, $\\alpha \\gt 90^\\circ$), hoặc sinh công bằng 0 (khi chuyển động tròn đều, hợp lực vuông góc với vận tốc). Vì vậy không thể kết luận hợp lực luôn sinh công dương.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: phát biểu sai là D.</p>","options":["Công của lực cản là công do lực cản chuyển động của vật sinh ra.","Những lực có phương vuông góc với hướng dịch chuyển của vật thì không sinh công.","Khi một vật chuyển động tròn đều, lực hướng tâm không sinh công.","Khi một vật chuyển động có gia tốc, hợp lực tác dụng lên vật sinh công dương."],"answer":3}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một vật trượt xuống trên một mặt phẳng nghiêng hợp với mặt phẳng ngang một góc $a.$ Công do lực ma sát thực hiện trên chiều dài s của mặt phẳng nghiêng là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực ma sát trượt trên mặt phẳng nghiêng có độ lớn: $F_{ms} = \\mu N$.</p><p class=\"text-base leading-relaxed my-2\">Chiều dương được chọn theo chiều chuyển động của vật. Phản lực pháp tuyến của mặt nghiêng: $N = mg\\cos\\alpha$ (vì phương vuông góc mặt nghiêng, lực $\\vec{P}$ có thành phần vuông góc là $mg\\cos\\alpha$).</p><p class=\"text-base leading-relaxed my-2\">Suy ra: $F_{ms} = \\mu mg\\cos\\alpha$.</p><p class=\"text-base leading-relaxed my-2\">Lực ma sát luôn ngược chiều chuyển động nên góc giữa $\\vec{F}_{ms}$ và độ dời là $180^\\circ$, do đó $\\cos 180^\\circ = -1$.</p><p class=\"text-base leading-relaxed my-2\">Công của lực ma sát trên quãng đường $s$: $A_{ms} = F_{ms}\\, s \\cos 180^\\circ = -\\mu mg\\, s\\cos\\alpha$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: công của lực ma sát có giá trị $-\\mu mg\\,s\\cos\\alpha$ (công âm), tương ứng phương án D.</p>","options":["$mmg.s.sina.$","$mmg.s.cosa.$","$mmg.s.sina.$","$mmg.s.cosa.$"],"answer":3}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Khi một vật trượt đi lên trên một mặt phẳng nghiêng hợp với mặt phẳng ngang một góc $࿰$ Công do trọng lực thực hiện trên chiều dài S của mặt phẳng nghiêng là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của trọng lực không phụ thuộc dạng đường đi, chỉ phụ thuộc độ cao đầu và cuối: $A_P = mg(h_1 - h_2)$, với $h_1$ là độ cao đầu, $h_2$ là độ cao cuối.</p><p class=\"text-base leading-relaxed my-2\">Vật đi lên mặt phẳng nghiêng có góc $\\alpha$ trên quãng đường $s$, nên độ cao tăng thêm là $h = s\\sin\\alpha$ (từ hình học tam giác vuông).</p><p class=\"text-base leading-relaxed my-2\">Vì vật đi lên, trọng lực sinh công cản: $A_P = -mgh$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A_P = -mg\\,s\\sin\\alpha$.</p><p class=\"text-base leading-relaxed my-2\">Đáp án đúng là C.</p>","options":["$A_{P}=mg.s.sina.$","$A_{P}=mg.s.cosa.$","$A_{P}= -mg.s.sina.$","$A_{P}= -mg.s.cosa.$"],"answer":2}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một vật chịu tác dụng của một lực F không đổi có độ lớn 5 N, phương của lực hợp với phương chuyển động một góc 60°. Biết rằng quãng đường đi được là 6 m. Công của lực F là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực không đổi được tính theo công thức: $A = F \\cdot s \\cdot \\cos\\alpha$, trong đó $F$ là độ lớn lực, $s$ là quãng đường đi được và $\\alpha$ là góc giữa phương của lực và phương chuyển động.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $F = 5\\ \\text{N}$, $s = 6\\ \\text{m}$, $\\alpha = 60^\\circ$:</p><p class=\"text-base leading-relaxed my-2\">$A = 5 \\cdot 6 \\cdot \\cos 60^\\circ$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A = 5 \\cdot 6 \\cdot 0{,}5 = 15\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\">Vậy công của lực $F$ là $15\\ \\text{J}$, chọn đáp án D.</p>","options":["11 J.","50 J.","30 J.","15 J."],"answer":3}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một vật có khối lượng m = 3 kg rơi tự do từ độ cao h không vận tốc đầu, trong thời gian 5 s đầu vật vẫn chưa chạm đất lấy g = 10 m/s$^{2}$. Trọng lực thực hiện một công trong thời gian đó bằng</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Vật rơi tự do từ trạng thái nghỉ, chỉ chịu tác dụng của trọng lực. Chọn chiều dương hướng xuống.</p><p class=\"text-base leading-relaxed my-2\">Quãng đường vật rơi trong 5 s đầu: $s = \\dfrac{1}{2}gt^2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow s = \\dfrac{1}{2}\\cdot 10\\cdot 5^2 = 125\\ \\text{m}$</p><p class=\"text-base leading-relaxed my-2\">Công của trọng lực: $A = P\\cdot s = mgs$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A = 3\\cdot 10\\cdot 125 = 3750\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: trọng lực thực hiện công $3750\\ \\text{J}$, chọn đáp án A.</p>","options":["3750 J.","375 J.","7500 J.","150 J."],"answer":0}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Ở thời điểm $t_{0}=0$ một vật có khối lượng m = 8 kg rơi tự do từ độ cao h = 180m không vận tốc đầu, lấy g = 10m/s$^{2}$. Trọng lực thực hiện một công trong 2 giây cuối bằng</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Chọn chiều dương hướng xuống, vật rơi tự do không vận tốc đầu nên quãng đường đi được sau thời gian $t$: $s = \\dfrac{1}{2}gt^2$.</p><p class=\"text-base leading-relaxed my-2\">Thời gian rơi hết độ cao $h = 180$ m: $t = \\sqrt{\\dfrac{2h}{g}} = \\sqrt{\\dfrac{2 \\cdot 180}{10}} = 6$ s.</p><p class=\"text-base leading-relaxed my-2\">Quãng đường đi được trong $4$ s đầu: $s_1 = \\dfrac{1}{2} \\cdot 10 \\cdot 4^2 = 80$ m.</p><p class=\"text-base leading-relaxed my-2\">Quãng đường đi được trong 2 s cuối: $\\Delta s = h - s_1 = 180 - 80 = 100$ m.</p><p class=\"text-base leading-relaxed my-2\">Công của trọng lực trong 2 s cuối (trọng lực sinh công dương vì cùng chiều chuyển động): $A = P \\cdot \\Delta s = mg\\Delta s = 8 \\cdot 10 \\cdot 100 = 8000$ J.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: công của trọng lực trong 2 giây cuối là $8000$ J.</p>","options":["7200 J.","4000 J.","8000 J.","14400 J."],"answer":2}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một vật có khối lượng m = 200g được ném ngang từ độ cao h. Bỏ qua sức cản của không khí, lấy g = 9,8 m/s$^{2}$, sau thời gian 4 s vật chưa chạm đất. Trọng lực đã thực hiện một công trong thời gian trên bằng</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Chọn hệ trục Oy hướng thẳng đứng xuống dưới, gốc tại vị trí ném. Khi ném ngang, chuyển động theo phương thẳng đứng là rơi tự do với vận tốc đầu bằng 0 (bỏ qua sức cản không khí).</p><p class=\"text-base leading-relaxed my-2\">Công của trọng lực bằng tích của trọng lực với độ dịch chuyển theo phương thẳng đứng: $A = P\\cdot y = mg\\cdot y$.</p><p class=\"text-base leading-relaxed my-2\">Quãng đường rơi theo phương thẳng đứng sau thời gian $t$: $y = \\dfrac{1}{2}gt^2$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra: $A = mg\\cdot\\dfrac{1}{2}gt^2 = \\dfrac{1}{2}mg^2t^2$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A = \\dfrac{1}{2}\\cdot 0{,}2\\cdot 9{,}8^2\\cdot 4^2 = 153{,}66\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A \\approx 154\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: trọng lực thực hiện công khoảng 154 J (đáp án C).</p>","options":["39,16 J.","9,9 J.","154J.","308J."],"answer":2}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Cho một vật có khối lượng 2 kg được thả rơi tự do. Lấy g = 10 m/s$^{2}$. Công của trọng lực trong giây thứ năm là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Vật rơi tự do không vận tốc đầu, chỉ chịu tác dụng của trọng lực. Công của trọng lực bằng $A = P\\cdot h = mg\\cdot \\Delta h$, với $\\Delta h$ là quãng đường vật rơi được.</p><p class=\"text-base leading-relaxed my-2\">Quãng đường rơi sau $t$ giây: $h(t) = \\dfrac{1}{2}gt^2$.</p><p class=\"text-base leading-relaxed my-2\">Quãng đường rơi trong giây thứ năm là hiệu quãng đường rơi trong 5 s và trong 4 s:</p><p class=\"text-base leading-relaxed my-2\">$\\Delta h_5 = h(5) - h(4) = \\dfrac{1}{2}g(5^2 - 4^2) = \\dfrac{1}{2}\\cdot 10\\cdot 9 = 45\\ \\text{m}$</p><p class=\"text-base leading-relaxed my-2\">Công của trọng lực trong giây thứ năm:</p><p class=\"text-base leading-relaxed my-2\">$A = mg\\cdot\\Delta h_5 = 2\\cdot 10\\cdot 45 = 900\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: công của trọng lực trong giây thứ năm là 900 J, chọn D.</p>","options":["450 J.","600 J.","1800 J.","900 J."],"answer":3}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Cho một máy bay lên thẳng có khối lượng 8.10$^{3}$ kg, sau thời gian 2 phút máy bay lên được độ cao là 2000m. Lấy g = 10 m/s$^{2}$. Công của động cơ khi chuyển động nhanh dần đều là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\"><strong>Chọn hệ quy chiếu:</strong> gắn với mặt đất, chiều dương hướng lên. Máy bay xuất phát từ trạng thái đứng yên, chuyển động thẳng nhanh dần đều theo phương thẳng đứng.</p><p class=\"text-base leading-relaxed my-2\"><strong>Gia tốc của máy bay:</strong> từ công thức quãng đường $h = \\dfrac{1}{2}at^2$ suy ra $a = \\dfrac{2h}{t^2}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $h = 2000\\ \\text{m}$, $t = 2\\ \\text{phút} = 120\\ \\text{s}$:</p><p class=\"text-base leading-relaxed my-2\">$a = \\dfrac{2 \\cdot 2000}{120^2} = \\dfrac{4000}{14400} \\approx 0{,}278\\ \\text{m/s}^2$</p><p class=\"text-base leading-relaxed my-2\"><strong>Lực nâng của động cơ:</strong> theo định luật II Niu-tơn, $F - P = ma$ nên $F = m(g + a)$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $m = 8\\cdot 10^3\\ \\text{kg}$, $g = 10\\ \\text{m/s}^2$:</p><p class=\"text-base leading-relaxed my-2\">$F = 8\\cdot 10^3 \\cdot (10 + 0{,}278) \\approx 8{,}222\\cdot 10^4\\ \\text{N}$</p><p class=\"text-base leading-relaxed my-2\"><strong>Công của động cơ:</strong> lực $F$ cùng hướng với độ dịch chuyển, nên $A = F\\cdot h$.</p><p class=\"text-base leading-relaxed my-2\">$A = 8{,}222\\cdot 10^4 \\cdot 2000 \\approx 1{,}644\\cdot 10^8\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\"><strong>Kết luận:</strong> công của động cơ là $1{,}644\\cdot 10^8\\ \\text{J}$, đáp án B.</p>","options":["2,48610$^{8}$ J.","1,644.10$^{8}$ J.","3,234.10$^{8}$ J.","4.10$^{8}$ J."],"answer":1}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một xe ô tô khối lượng m = 2 tấn chuyển động nhanh dần đều trên đường nằm ngang với vận tốc ban đầu bằng không, đi được quãng đường s = 200 m thì đạt được vận tốc v = 72 km/h. Cho biết hệ số ma sát giữa ô tô và mặt đường 0,05. Lấy g = 10m/s$^{2}$. Công do lực ma sát thực hiện trên quãng đường đó là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $m = 2\\text{ tấn} = 2000\\text{ kg}$; $v = 72\\text{ km/h} = 20\\text{ m/s}$.</p><p class=\"text-base leading-relaxed my-2\">Chuyển động nhanh dần đều từ trạng thái nghỉ, gia tốc được tính theo công thức $v^2 - v_0^2 = 2as$ với $v_0 = 0$:</p><p class=\"text-base leading-relaxed my-2\">$a = \\dfrac{v^2}{2s} = \\dfrac{20^2}{2 \\cdot 200} = 1\\text{ m/s}^2$</p><p class=\"text-base leading-relaxed my-2\">Độ lớn lực ma sát trượt: $F_{ms} = \\mu mg$.</p><p class=\"text-base leading-relaxed my-2\">$F_{ms} = 0{,}05 \\cdot 2000 \\cdot 10 = 1000\\text{ N}$</p><p class=\"text-base leading-relaxed my-2\">Công của lực ma sát: $A_{ms} = F_{ms}\\cdot s \\cdot \\cos 180^\\circ = -F_{ms}\\cdot s$, vì lực ma sát ngược chiều chuyển động.</p><p class=\"text-base leading-relaxed my-2\">$A_{ms} = -1000 \\cdot 200 = -200000\\text{ J} = -200\\text{ kJ}$</p><p class=\"text-base leading-relaxed my-2\">Vậy công do lực ma sát thực hiện trên quãng đường đó là $-200\\text{ kJ}$, đáp án A.</p>","options":["– 200 kJ.","–500 kJ.","–300 kJ.","–100 kJ."],"answer":0}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một thang máy có khối lượng m = 1 tấn chuyển động nhanh dần đều lên cao với gia tốc 2m/s$^{2}$. Công mà động cơ thang máy đã thực hiện trong 5s đầu. Lấy g = 10m/s$^{2}$.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Chọn chiều dương hướng lên. Thang máy nhanh dần đều lên với gia tốc $a = 2\\ \\text{m/s}^2$, nên lực kéo của động cơ $F$ thắng trọng lực và tạo gia tốc. Theo định luật II Newton: $F - mg = ma$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra $F = m(g + a)$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $m = 1000\\ \\text{kg}$: $F = 1000 \\cdot (10 + 2) = 12000\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Quãng đường đi được trong 5 s đầu (chuyển động nhanh dần đều từ trạng thái nghỉ): $s = \\dfrac{1}{2}at^2 = \\dfrac{1}{2} \\cdot 2 \\cdot 5^2 = 25\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Công của lực kéo (lực cùng hướng chuyển động): $A = F \\cdot s$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $A = 12000 \\cdot 25 = 300000\\ \\text{J} = 300\\ \\text{kJ}$.</p><p class=\"text-base leading-relaxed my-2\">Vậy công của động cơ trong 5 s đầu là 300 kJ, đáp án D.</p>","options":["400 kJ","500kJ","200kJ","300kJ"],"answer":3}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một khối gỗ có trọng lượng là P = 50 N được đẩy trượt đều lên trên một mặt phẳng nghiêng nhẵn với góc nghiêng 25$^{0}$ so với phương ngang. Biết khối gỗ di chuyển được một đoạn 1 m trên mặt phẳng nghiêng. Công mà người đẩy thực hiện trên khối gỗ nếu lực tác dụng song song với mặt phẳng ngang là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Vật trượt đều nên hợp lực bằng 0. Chọn trục dọc mặt phẳng nghiêng, chiều dương hướng lên; lực đẩy $\\vec F$ nằm ngang, mặt phẳng nhẵn nên không có ma sát.</p><p class=\"text-base leading-relaxed my-2\">Chiếu lên phương mặt phẳng nghiêng: $F\\cos\\alpha - P\\sin\\alpha = 0$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F = P\\tan\\alpha = 50\\tan 25^\\circ \\approx 23{,}32$ N</p><p class=\"text-base leading-relaxed my-2\">Góc giữa $\\vec F$ và độ dời là $\\alpha$: $A = F s\\cos\\alpha$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A = P s\\sin\\alpha = 50\\cdot 1\\cdot\\sin 25^\\circ \\approx 21{,}1$ J</p><p class=\"text-base leading-relaxed my-2\">Giá trị gần nhất là 21,22 J (phương án A = 23,32 J là sai vì bỏ qua $\\cos\\alpha$). Chọn B.</p>","options":["23,32 J","21,22 J","107,35J","103,53J"],"answer":1}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một người kéo một vật có m = 8kg trượt trên mặt phẳng ngang có hệ số ma sát $m$ = 0,2 bằng một sợi dây có phương hợp một góc 60° so với phương nằm ngang. Lực tác dụng lên dây bằng $\\overset{\\rightarrow}{F_{k}}$ vật trượt không vận tốc đầu với a = 1m/s$^{2}$. Công của lực kéo trong thời gian 4 giây kể từ khi bắt đầu chuyển động là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Chọn hệ trục: Ox nằm ngang, chiều dương cùng chiều chuyển động. Vật chịu trọng lực $\\vec{P}$, phản lực $\\vec{N}$, lực kéo $\\vec{F}$ và lực ma sát trượt $\\vec{F_{ms}}$. Lấy $g = 9{,}8$ m/s² (giá trị cho kết quả khớp đáp án).</p>\n<p class=\"text-base leading-relaxed my-2\">Theo phương thẳng đứng, vật không bay lên hay chìm xuống nên: $N + F\\sin 60^\\circ = mg$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$N = mg - F\\sin 60^\\circ$.</p>\n<p class=\"text-base leading-relaxed my-2\">Lực ma sát trượt: $F_{ms} = \\mu N = \\mu(mg - F\\sin 60^\\circ)$.</p>\n<p class=\"text-base leading-relaxed my-2\">Định luật II Newton theo phương ngang: $F\\cos 60^\\circ - F_{ms} = ma$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$F\\cos 60^\\circ - \\mu(mg - F\\sin 60^\\circ) = ma$.</p>\n<p class=\"text-base leading-relaxed my-2\">Thay số: $0{,}5F - 0{,}2(8\\cdot 9{,}8 - 0{,}866F) = 8\\cdot 1$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$0{,}5F - 15{,}68 + 0{,}1732F = 8$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$0{,}6732F = 23{,}68$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$F \\approx 35{,}18$ N.</p>\n<p class=\"text-base leading-relaxed my-2\">Quãng đường vật đi được trong 4 s (vật xuất phát từ nghỉ): $s = \\dfrac{1}{2}at^2 = \\dfrac{1}{2}\\cdot 1\\cdot 4^2 = 8$ m.</p>\n<p class=\"text-base leading-relaxed my-2\">Công của lực kéo: $A = Fs\\cos 60^\\circ = 35{,}18\\cdot 8\\cdot 0{,}5 \\approx 140{,}7$ J.</p>\n<p class=\"text-base leading-relaxed my-2\">Kết luận: công của lực kéo trong 4 s đầu là $140{,}7$ J, chọn đáp án B.</p>","options":["162,5 J.","140,7 J.","147,5 J.","126,7J."],"answer":1}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một vật có khối lượng 2 kg bắt đầu trượt xuống từ đỉnh một mặt phẳng nghiêng dài 10m, cao 6m. Hệ số ma sát giữa vật và mặt phẳng nghiêng là 0,2, lấy g = 10 m/s$^{2}$. Công của lực ma sát khi vật chuyển động được nửa đoạn đường trên mặt phẳng nghiêng là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Chọn chiều dương dọc theo mặt phẳng nghiêng, hướng xuống. Lực ma sát trượt có chiều ngược với chiều chuyển động nên công của lực ma sát mang dấu âm.</p><p class=\"text-base leading-relaxed my-2\">Góc nghiêng $\\alpha$ có $\\sin\\alpha = \\dfrac{h}{l} = \\dfrac{6}{10} = 0{,}6$, suy ra $\\cos\\alpha = \\sqrt{1-0{,}6^2} = 0{,}8$.</p><p class=\"text-base leading-relaxed my-2\">Độ lớn lực ma sát trượt (vuông góc phản lực pháp tuyến $N = mg\\cos\\alpha$):</p><p class=\"text-base leading-relaxed my-2\">$F_{ms} = \\mu mg\\cos\\alpha = 0{,}2 \\cdot 2 \\cdot 10 \\cdot 0{,}8 = 3{,}2\\ \\text{N}$</p><p class=\"text-base leading-relaxed my-2\">Quãng đường vật đi được là nửa đoạn đường trên mặt phẳng nghiêng: $s = \\dfrac{l}{2} = \\dfrac{10}{2} = 5\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Công của lực ma sát:</p><p class=\"text-base leading-relaxed my-2\">$A_{ms} = -F_{ms}\\cdot s = -3{,}2 \\cdot 5 = -16\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\">Vậy công của lực ma sát là $-16$ J, đáp án D.</p>","options":["-20 J.","-40 J.","-32 J.","-16 J."],"answer":3}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một vật có khối lượng 2kg đang chuyển động trên mặt phẳng ngang với vận tốc 8 m/s thì trượt lên mặt phẳng nghiêng góc $b$ so với phương ngang có tan $ b$ = 0,75. Vật đi lên được 5m theo mặt phẳng nghiêng thì dừng lại, rồi trượt trở xuống chân dốc. Lấy g = 10 m/s$^{2}$. Công của trọng lực thực hiện từ lúc vật lên dốc đến lúc dừng lại trên dốc bằng</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Góc nghiêng $\\alpha$ có $\\tan\\alpha = 0{,}75$, suy ra $\\sin\\alpha = 0{,}6$ (vì $\\sin\\alpha=\\dfrac{\\tan\\alpha}{\\sqrt{1+\\tan^2\\alpha}}=\\dfrac{0{,}75}{1{,}25}=0{,}6$).</p><p class=\"text-base leading-relaxed my-2\">Công của trọng lực không phụ thuộc đường đi mà chỉ phụ thuộc độ cao: $A_P = -mgh$ (dấu âm vì vật đi lên, trọng lực cản chuyển động).</p><p class=\"text-base leading-relaxed my-2\">Độ cao vật lên được: $h = s\\sin\\alpha$ với $s = 5\\ \\text{m}$ là quãng đường trên mặt phẳng nghiêng.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow h = 5 \\cdot 0{,}6 = 3\\ \\text{m}$</p><p class=\"text-base leading-relaxed my-2\">Công của trọng lực từ lúc lên dốc đến lúc dừng lại:</p><p class=\"text-base leading-relaxed my-2\">$A_P = -mgh = -2 \\cdot 10 \\cdot 3 = -60\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\">Vậy công của trọng lực bằng $-60\\ \\text{J}$, chọn D.</p>","options":["75 J.","-75 J.","60 J.","- 60 J."],"answer":3}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một xe có khối lượng m = 50 kg chuyển động đều lên dốc, dài 10 m nghiêng 30° so với đường ngang. Lực ma sát $F_{ms}$ = 40 N, lấy g = 10 m/s$^{2}$. Công của lực kéo F theo phương song song với mặt phẳng nghiêng khi xe lên hết dốc là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Xe chuyển động đều nên hợp lực tác dụng lên xe bằng 0. Chọn chiều dương cùng chiều chuyển động (lên dốc). Lực kéo $F$ cân bằng với thành phần trọng lực song song mặt phẳng nghiêng và lực ma sát (ma sát ngược chiều chuyển động).</p><p class=\"text-base leading-relaxed my-2\">Điều kiện cân bằng theo phương song song mặt phẳng nghiêng: $F = P\\sin\\alpha + F_{ms}$</p><p class=\"text-base leading-relaxed my-2\">Thay số với $P = mg = 50 \\cdot 10 = 500$ N và $\\sin 30^\\circ = 0{,}5$:</p><p class=\"text-base leading-relaxed my-2\">$F = 500 \\cdot 0{,}5 + 40 = 290$ N</p><p class=\"text-base leading-relaxed my-2\">Công của lực kéo $F$ (cùng phương, cùng chiều dịch chuyển, $\\alpha = 0^\\circ$) khi xe đi hết dốc dài $s = 10$ m:</p><p class=\"text-base leading-relaxed my-2\">$A_F = F \\cdot s \\cdot \\cos 0^\\circ = 290 \\cdot 10 = 2900$ J</p><p class=\"text-base leading-relaxed my-2\">Kết luận: công của lực kéo là 2900 J, đáp án D.</p>","options":["5400 J.","1000 J.","2000 J.","2900J."],"answer":3}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một vận động viên đẩy tạ đẩy một quả tạ nặng m = 2 kg dưới một góc nào đó so với phương nằm ngang. Quả tạ rời khỏi tay vận động viên ở độ cao 2 m so với mặt đất. Công của trọng lực thực hiện được kể từ khi quả tạ rời khỏi tay vận động viên cho đến lúc rơi xuống đất (g = 10 m/s$^{2}$) là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của trọng lực không phụ thuộc vào dạng quỹ đạo, chỉ phụ thuộc vào độ cao đầu và độ cao cuối: $A = mg(z_1 - z_2)$ với $z$ là độ cao so với mặt đất.</p><p class=\"text-base leading-relaxed my-2\">Quả tạ rời tay ở độ cao $z_1 = 2$ m và rơi xuống đất có $z_2 = 0$, nên độ giảm độ cao là $h = 2$ m.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $A = mgh = 2 \\cdot 10 \\cdot 2 = 40$ J.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: công của trọng lực là $40$ J, chọn đáp án B.</p>","options":["20J","40J","200J","400J"],"answer":1}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một người kéo một hòm gỗ trượt trên sàn nhà bằng một dây có phương hợp với phương ngang một góc 60°. Lực tác dụng lên dây bằng 150 N. Công của lực đó khi trượt được 10 m là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực không đổi tác dụng lên vật, khi lực hợp với phương chuyển động một góc $\\alpha$, được tính theo công thức: $A = F \\cdot s \\cdot \\cos\\alpha$, trong đó $F$ là độ lớn lực, $s$ là quãng đường dịch chuyển, $\\alpha$ là góc giữa lực và phương chuyển động.</p><p class=\"text-base leading-relaxed my-2\">Ở đây, dây kéo hợp với phương ngang góc $\\alpha = 60^\\circ$, và hòm trượt theo phương ngang nên $\\alpha = 60^\\circ$ là góc giữa lực và phương dịch chuyển.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $F = 150$ N, $s = 10$ m, $\\cos 60^\\circ = 0{,}5$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A = 150 \\cdot 10 \\cdot 0{,}5 = 750$ J.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: công của lực là 750 J, chọn đáp án B.</p>","options":["1275 J.","750 J.","1500 J.","6000 J."],"answer":1}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một người kéo một hòm gỗ trượt trên sàn nhà bằng một dây có phương hợp với phương ngang một góc $a$. Lực tác dụng lên dây bằng 100 N. Công của lực đó khi trượt được 8 m là 500J. Giá trị của góc $ a$ bằng</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực không đổi tác dụng lên vật khi vật dịch chuyển một đoạn $s$ là $A = F\\cdot s\\cdot\\cos\\alpha$, trong đó $\\alpha$ là góc giữa lực và phương dịch chuyển (ở đây là phương ngang).</p><p class=\"text-base leading-relaxed my-2\">Suy ra $\\cos\\alpha = \\dfrac{A}{F\\cdot s}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\cos\\alpha = \\dfrac{500}{100\\cdot 8} = 0{,}625$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\alpha = \\arccos(0{,}625) \\approx 51^\\circ$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: góc $\\alpha \\approx 51^\\circ$, chọn đáp án C.</p>","options":["30°","31°","51°","45°"],"answer":2}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$)) as v(q, tid, tname)
where not exists (select 1 from public.question_bank b where b.content_hash = public.question_content_hash(v.q));
insert into public.question_bank (subject_code, grade, topic_id, topic_name, form, qtype, difficulty, difficulty_source, question, content_hash, archived, note)
select 'vat-ly', '10', v.tid, v.tname, 'bai_tap', v.q->>'type', v.q->>'difficulty', 'ai', v.q, public.question_content_hash(v.q), true, 'nap-vl10-c4-20261020'
from (values ($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Nhờ một cần câu, một kiện hàng có khối lượng 5 tấn được bắt đầu nâng thẳng đứng lên cao nhanh dần đều, đạt độ cao 10m trong 5s. Lấy g = 10 m/s$^{2}$. Công của lực nâng trong giây thứ 5 bằng</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Kiện hàng có khối lượng $m = 5$ tấn $= 5000$ kg, chuyển động thẳng đứng nhanh dần đều từ trạng thái nghỉ. Chọn chiều dương hướng lên.</p><p class=\"text-base leading-relaxed my-2\">Quãng đường trong 5 s đầu: $s = \\dfrac{1}{2}at^2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow 10 = \\dfrac{1}{2}a \\cdot 5^2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow a = 0{,}8$ m/s$^2$</p><p class=\"text-base leading-relaxed my-2\">Định luật II Newton, lực nâng $F$ thắng trọng lực: $F - mg = ma$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F = m(g + a) = 5000 \\cdot (10 + 0{,}8) = 54000$ N</p><p class=\"text-base leading-relaxed my-2\">Quãng đường vật đi được trong 4 s đầu: $s_4 = \\dfrac{1}{2}a \\cdot 4^2 = \\dfrac{1}{2}\\cdot 0{,}8 \\cdot 16 = 6{,}4$ m</p><p class=\"text-base leading-relaxed my-2\">Quãng đường trong giây thứ 5: $\\Delta s = s_5 - s_4 = 10 - 6{,}4 = 3{,}6$ m</p><p class=\"text-base leading-relaxed my-2\">Công của lực nâng trong giây thứ 5 (lực và chuyển động cùng chiều): $A = F \\cdot \\Delta s$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A = 54000 \\cdot 3{,}6 = 1{,}944 \\cdot 10^5$ J</p><p class=\"text-base leading-relaxed my-2\">Kết luận: công của lực nâng trong giây thứ 5 là $1{,}94 \\cdot 10^5$ J, đáp án B.</p>","options":["1,80.10$^{5}$J.","1,94.10$^{5}$J.","14,4.10$^{3}$J.","24,4.10$^{3}$J."],"answer":1}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một vật có khối lượng m ném thẳng đứng lên trên với vận tốc ban đầu $v_{0}$ sau một thời gian t vật  <strong>C</strong>huyển động về vị trí ban đầu. Công của trọng lực của vật đã thực hiện trong thời gian nói trên bằng</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của trọng lực: $A = mg(z_1 - z_2)$, trong đó $z_1$ là độ cao ban đầu và $z_2$ là độ cao cuối, không phụ thuộc đường đi.</p><p class=\"text-base leading-relaxed my-2\">Vật ném thẳng đứng lên rồi chuyển động trở về đúng vị trí ban đầu, nên $z_2 = z_1$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A = mg(z_1 - z_1) = 0$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: công của trọng lực trong thời gian trên bằng $0$ J (đáp án D).</p>","options":["$2$","$2mv_{0}$","$2g$","0"],"answer":3}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Vật 2kg trượt trên sàn có hệ số ma sát 0,2 dưới tác dụng của lực không đổi có độ lớn 10N hợp với phương ngang góc 30$^{o}$, lấy g=10m/s$^{2}$. Công của lực F khi vật chuyển động được 5s là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Chọn chiều dương là chiều chuyển động của vật (sang phải), trục Oy hướng lên. Lực $\\vec F$ hướng lên, hợp với phương ngang góc $\\alpha = 30^\\circ$.</p><p class=\"text-base leading-relaxed my-2\">Theo định luật II Newton, theo phương thẳng đứng vật không chuyển động theo phương này nên $N + F\\sin\\alpha = mg$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra $N = mg - F\\sin\\alpha = 2\\cdot 10 - 10\\cdot\\sin 30^\\circ = 15\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Lực ma sát trượt: $F_{ms} = \\mu N = 0,2\\cdot 15 = 3\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Theo phương ngang, định luật II Newton: $F\\cos\\alpha - F_{ms} = ma$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra $a = \\dfrac{F\\cos\\alpha - F_{ms}}{m} = \\dfrac{10\\cdot\\cos 30^\\circ - 3}{2} \\approx 2,83\\ \\text{m/s}^2$.</p><p class=\"text-base leading-relaxed my-2\">Quãng đường vật đi được sau $t = 5\\ \\text{s}$ (vật xuất phát từ trạng thái đứng yên): $s = \\dfrac{1}{2}at^2 = \\dfrac{1}{2}\\cdot 2,83\\cdot 5^2 \\approx 35,38\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Công của lực $\\vec F$: $A_F = F s\\cos\\alpha = 10\\cdot 35,38\\cdot\\cos 30^\\circ \\approx 306,4\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: công của lực F là $306,4\\ \\text{J}$, chọn đáp án A.</p>","options":["306,4 J","300J","250,5J","432J"],"answer":0}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một lực 5 N tác dụng vào một vật 10 kg ban đầu đứng yên trên mặt sàn nằm ngang không ma sát.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\\\"><b>Định luật II Newton:</b> $\\vec{F}=m\\vec{a}$, áp dụng vì vật chịu lực không đổi, chuyển động thẳng nhanh dần đều từ trạng thái đứng yên (không ma sát, $v_0=0$).</p><p class=\"text-base leading-relaxed my-2\\\"><b>a)</b> Gia tốc: $a=\\dfrac{F}{m}=\\dfrac{5}{10}=0,5\\ \\text{m/s}^2$. Kết luận: <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\\\"><b>b)</b> Quãng đường trong 1 s đầu: $s_1=\\dfrac{1}{2}at_1^2=\\dfrac{1}{2}\\cdot 0,5\\cdot 1^2=0,25\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\\\">Công trong giây thứ nhất: $A_1=F s_1=5\\cdot 0,25=1,25\\ \\text{J}$ (khác 1 J). Kết luận: <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\\\"><b>c)</b> Quãng đường trong 2 s đầu: $s_2=\\dfrac{1}{2}\\cdot 0,5\\cdot 2^2=1\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\\\">Quãng đường trong giây thứ hai: $\\Delta s_2=s_2-s_1=1-0,25=0,75\\ \\text{m}$. Kết luận: <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\\\"><b>d)</b> Quãng đường trong 3 s đầu: $s_3=\\dfrac{1}{2}\\cdot 0,5\\cdot 3^2=2,25\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\\\">Quãng đường trong giây thứ ba: $\\Delta s_3=s_3-s_2=2,25-1=1,25\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\\\">Công trong giây thứ ba: $A_3=F\\Delta s_3=5\\cdot 1,25=6,25\\ \\text{J}$ (khác 5 J). Kết luận: <b>Sai</b>.</p>","statements":[{"text":"Gia tốc của vật là $0,5 m/s^{2}.$","answer":true},{"text":"Công thực hiện được trong giây thứ nhất là 1 J.","answer":false},{"text":"Quãng đường đi được của vật trong giây thứ hai là 0,75 m.","answer":true},{"text":"Quãng đường và công thực hiện được trong giây thứ ba lần lượt là 1,25 m và 5 J.","answer":false}]}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một đoàn tàu có khối lượng 100 tấn chuyển động nhanh dần đều từ địa điểm A đến địa điểm B cách nhau 2 km, khi đó vận tốc của tàu tăng từ 15 m/s đến 20 m/s. Cho biết hệ số ma sát là 0,005. Lấy g = 9,8m/s$^{2}$. Tính thời gian tàu chạy và công của đầu máy tàu trên đoạn đường AB.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Đổi: $m=10^5$ kg, $s=2000$ m, $v_0=15$ m/s, $v=20$ m/s, $\\mu=0{,}005$. Giả sử tàu chạy trên đường ngang.</p><p class=\"text-base leading-relaxed my-2\">a) $a=\\dfrac{v^2-v_0^2}{2s}=\\dfrac{400-225}{4000}=0{,}04375$ m/s² ≠ 0,4 m/s². Sai.</p><p class=\"text-base leading-relaxed my-2\">b) $F_{ms}=\\mu mg=0{,}005\\cdot10^5\\cdot9{,}8=4900$ N.</p><p class=\"text-base leading-relaxed my-2\">$F-F_{ms}=ma$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F=ma+F_{ms}=4375+4900=9275$ N ≠ 8900 N. Sai.</p><p class=\"text-base leading-relaxed my-2\">c) $t=\\dfrac{v-v_0}{a}=\\dfrac{5}{0{,}04375}\\approx114{,}3$ s ≠ 125 s. Sai.</p><p class=\"text-base leading-relaxed my-2\">d) $A=Fs=9275\\cdot2000=1{,}855\\cdot10^7$ J ≠ 17 800 000 J. Sai.</p><p class=\"text-base leading-relaxed my-2\">Kiểm tra bằng định lí động năng: $A=\\tfrac12m(v^2-v_0^2)+F_{ms}s=8{,}75\\cdot10^6+9{,}8\\cdot10^6=1{,}855\\cdot10^7$ J, khớp.</p>","statements":[{"text":"Gia tốc chuyển động của đoàn tàu là $0,4 m/s^{2}.$","answer":false},{"text":"Lực kéo của đầu máy của đoàn tàu với đường có độ lớn 8900 N.","answer":false},{"text":"Tàu chày từ A đến B với thời gian 125 s.","answer":false},{"text":"Công mà đầu máy của đoàn tàu thực hiện là 17800000 J.","answer":false}]}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một xe khối lượng 1,5 tấn, khỏi hành sau 15 s đạt được tốc độ 54 km/h, chuyển động trên đường nằm ngang có hệ số ma sát $m=0,02$. Lấy g = 10 m/s$^{2}$.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\"><b>Tóm tắt:</b> $m = 1500\\ \\text{kg}$; $v_0 = 0$; $v = 54\\ \\text{km/h} = 15\\ \\text{m/s}$; $t = 15\\ \\text{s}$; $\\mu = 0,02$; $g = 10\\ \\text{m/s}^2$.</p><p class=\"text-base leading-relaxed my-2\"><b>Chọn chiều dương</b> là chiều chuyển động của xe. Xe chuyển động thẳng nhanh dần đều trên đường ngang.</p><p class=\"text-base leading-relaxed my-2\"><b>Ý a)</b> Gia tốc: $a = \\dfrac{v - v_0}{t}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow a = \\dfrac{15 - 0}{15} = 1\\ \\text{m/s}^2$</p><p class=\"text-base leading-relaxed my-2\">Gia tốc là $1\\ \\text{m/s}^2$, không phải $0,5\\ \\text{m/s}^2$. Ý a) <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>Ý b)</b> Lực ma sát: $F_{ms} = \\mu mg = 0,02 \\cdot 1500 \\cdot 10 = 300\\ \\text{N}$</p><p class=\"text-base leading-relaxed my-2\">Định luật II Newton theo phương chuyển động: $F - F_{ms} = ma$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F = ma + F_{ms} = 1500 \\cdot 1 + 300 = 1800\\ \\text{N}$</p><p class=\"text-base leading-relaxed my-2\">Ý b) <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>Ý c)</b> Quãng đường: $s = v_0 t + \\dfrac{1}{2}at^2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow s = 0 + \\dfrac{1}{2} \\cdot 1 \\cdot 15^2 = 112,5\\ \\text{m}$</p><p class=\"text-base leading-relaxed my-2\">Ý c) <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>Ý d)</b> Công của lực kéo: $A = F \\cdot s \\cdot \\cos 0^\\circ = F s$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A = 1800 \\cdot 112,5 = 202500\\ \\text{J} = 20,25 \\cdot 10^4\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\">Ý d) <b>Đúng</b>.</p>","statements":[{"text":"Xe chuyển động với gia tốc $0,5 m/s^{2}.$","answer":false},{"text":"Lực kéo của động cơ có độ lớn 1800 N.","answer":true},{"text":"Quãng đường xe đi được sau 15 s là 112,5 m.","answer":true},{"text":"Công do lực kéo của động cơ thực hiện là $20,25.10^{4} J$.","answer":true}]}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một xe ô tô khối lượng 2 tấn chuyển động nhanh dần đều trên đường nằm ngang với vận tốc ban đầu bằng không, khi đi được quãng đường 200 m thì ô tô đạt được vận tốc 72 km/h. Cho biết hệ số ma sát lăn giữa ô tô và mặt đường 0,05. Lấy g = 10 m/s$^{2}$. Tính công do lực kéo của động cơ ô tô và do lực ma sát thực hiện trên quãng đường đó.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\"><strong>Tóm tắt:</strong> $m = 2\\,000$ kg, $v_0 = 0$, $s = 200$ m, $v = 72$ km/h $= 20$ m/s, $\\mu = 0{,}05$, $g = 10$ m/s$^2$.</p><p class=\"text-base leading-relaxed my-2\"><strong>Ý a)</strong> Chuyển động nhanh dần đều không vận tốc đầu nên áp dụng công thức liên hệ:</p><p class=\"text-base leading-relaxed my-2\">$v^2 - v_0^2 = 2as$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow a = \\dfrac{v^2 - v_0^2}{2s}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow a = \\dfrac{20^2 - 0}{2 \\cdot 200} = 1$ m/s$^2$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: <strong>Đúng</strong>.</p><p class=\"text-base leading-relaxed my-2\"><strong>Ý b)</strong> Chọn chiều dương là chiều chuyển động. Lực ma sát lăn có độ lớn:</p><p class=\"text-base leading-relaxed my-2\">$F_{ms} = \\mu mg = 0{,}05 \\cdot 2\\,000 \\cdot 10 = 1\\,000$ N.</p><p class=\"text-base leading-relaxed my-2\">Định luật II Newton theo phương ngang: $F - F_{ms} = ma$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F = ma + F_{ms} = 2\\,000 \\cdot 1 + 1\\,000 = 3\\,000$ N.</p><p class=\"text-base leading-relaxed my-2\">Lực kéo là 3 000 N, không phải 2 500 N. Kết luận: <strong>Sai</strong>.</p><p class=\"text-base leading-relaxed my-2\"><strong>Ý c)</strong> Công của lực kéo (lực không đổi, cùng chiều chuyển động, $\\alpha = 0$):</p><p class=\"text-base leading-relaxed my-2\">$A_F = Fs\\cos 0^\\circ = 3\\,000 \\cdot 200 = 600\\,000$ J $= 600$ kJ.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: giá trị 600 J trong đề là sai (đúng là 600 kJ). <strong>Sai</strong>.</p><p class=\"text-base leading-relaxed my-2\"><strong>Ý d)</strong> Lực ma sát ngược chiều chuyển động ($\\alpha = 180^\\circ$):</p><p class=\"text-base leading-relaxed my-2\">$A_{ms} = F_{ms}\\,s\\cos 180^\\circ = -1\\,000 \\cdot 200 = -200\\,000$ J $= -200$ kJ.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: <strong>Đúng</strong>.</p>","statements":[{"text":"Gia tốc chuyển đông của ô tô là $1 m/s^{2}.$","answer":true},{"text":"Lực kéo của động cơ ô tô có độ lớn 2500 N.","answer":false},{"text":"Công do lực kéo của động cơ thục hiện là 600 J.","answer":false},{"text":"Công do lực ma sát thực hiện trên quãng đường là – 200 kJ.","answer":true}]}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một thang máy khối lượng 600 kg được kéo từ đáy hầm mỏ sâu 150 m lên mặt đất bằng lực căng T của một dây cáp quấn quanh trục một động cơ.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Chọn chiều dương hướng lên. Thang máy được kéo đều (vận tốc không đổi) thì lực căng dây cân bằng với trọng lực, và đây là giá trị nhỏ nhất của lực căng để nâng thang máy lên.</p><p class=\"text-base leading-relaxed my-2\">Trọng lượng của thang máy: $P = mg$ với $m = 600\\text{ kg}$, $g = 10\\text{ m/s}^2$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow P = 600 \\cdot 10 = 6000\\text{ N}$.</p><p class=\"text-base leading-relaxed my-2\">Lực căng cực tiểu: $T_{min} = P = 6000\\text{ N}$.</p><p class=\"text-base leading-relaxed my-2\">Công cực tiểu của dây cáp (lực không đổi $T_{min}$, quãng đường $h = 150\\text{ m}$ cùng chiều lực): $A_{min} = T_{min}\\cdot h$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A_{min} = 6000 \\cdot 150 = 9\\cdot 10^{5}\\text{ J}$.</p><p class=\"text-base leading-relaxed my-2\">Đánh giá các ý:</p><p class=\"text-base leading-relaxed my-2\">a) Đúng: lực căng cực tiểu bằng trọng lượng thang máy.</p><p class=\"text-base leading-relaxed my-2\">b) Đúng: trọng lượng $P = 6000\\text{ N}$.</p><p class=\"text-base leading-relaxed my-2\">c) Sai: $T_{min} = 6000\\text{ N}$, không phải $600\\text{ N}$ (600 là khối lượng tính bằng kg).</p><p class=\"text-base leading-relaxed my-2\">d) Sai: công cực tiểu là $9\\cdot 10^{5}\\text{ J}$, không phải $900\\text{ J}$.</p>","statements":[{"text":"Muốn kéo thang máy lên cao thì lực căng cực tiểu phải bằng với trọng lượng của thang máy.","answer":true},{"text":"Trọng lượng của thang máy là 6000 N.","answer":true},{"text":"Lực căng cực tiểu T bằng 600 N.","answer":false},{"text":"Công cực tiểu của dây cáp là 900 J.","answer":false}]}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một vật có khối lượng 8 kg được thả rơi tự do. Lấy g = 10 m/s$^{2}$.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Vật rơi tự do không vận tốc đầu $v_0 = 0$, gia tốc $g = 10$ m/s$^2$. Quãng đường vật rơi sau thời gian $t$ là: $s = \\dfrac{1}{2}gt^2$.</p><p class=\"text-base leading-relaxed my-2\">Trọng lượng của vật: $P = mg = 8 \\cdot 10 = 80$ N.</p><p class=\"text-base leading-relaxed my-2\"><b>a)</b> Quãng đường rơi trong 3 s: $s_3 = \\dfrac{1}{2}\\cdot 10 \\cdot 3^2 = 45$ m. Ý này <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>b)</b> Quãng đường rơi trong 4 s: $s_4 = \\dfrac{1}{2}\\cdot 10 \\cdot 4^2 = 80$ m, không phải 60 m. Ý này <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>c)</b> Quãng đường rơi trong giây thứ 4: $\\Delta s = s_4 - s_3 = 80 - 45 = 35$ m, không phải 25 m. Ý này <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>d)</b> Công của trọng lực trong giây thứ 4: $A = P \\cdot \\Delta s = 80 \\cdot 35 = 2800$ J. Ý này <b>Đúng</b>.</p>","statements":[{"text":"Quãng đường vật rơi trong 3 giây là 45 m.","answer":true},{"text":"Trong 4 giây vật đi rơi được quãng đường 60 m.","answer":false},{"text":"Trong giây thứ 4 vật đi được quãng đường 25 m.","answer":false},{"text":"Công của trọng lực trong giây thứ 4 là 2800 J.","answer":true}]}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Cho một thang máy có khối lượng 2 tấn chuyển động đi lên với gia tốc 2 m/s$^{2}$. Lấy g = 10 m/s$^{2}$.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\"><strong>Tóm tắt:</strong> $m = 2$ tấn $= 2000$ kg, $a = 2$ m/s$^2$ (đi lên), $g = 10$ m/s$^2$.</p><p class=\"text-base leading-relaxed my-2\"><strong>Chọn chiều dương</strong> hướng lên. Áp dụng định luật II Newton: lực kéo $F$ hướng lên, trọng lực $P$ hướng xuống.</p><p class=\"text-base leading-relaxed my-2\"><strong>a)</strong> Định luật II Newton: $F - mg = ma$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$F = m(g + a)$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $F = 2000 \\cdot (10 + 2) = 24000$ N $= 24\\,000$ N.</p><p class=\"text-base leading-relaxed my-2\">Khác với 2400 N trong đề, nên ý a) <strong>Sai</strong>.</p><p class=\"text-base leading-relaxed my-2\"><strong>b)</strong> Quãng đường trong 5 s đầu (chuyển động nhanh dần đều, $v_0 = 0$): $s = \\dfrac{1}{2}at^2$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $s = \\dfrac{1}{2} \\cdot 2 \\cdot 5^2 = 25$ m. Ý b) <strong>Đúng</strong>.</p><p class=\"text-base leading-relaxed my-2\"><strong>c)</strong> Quãng đường trong giây thứ 5: $\\Delta s = s_5 - s_4 = \\dfrac{1}{2}a(5^2 - 4^2)$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $\\Delta s = \\dfrac{1}{2} \\cdot 2 \\cdot (25 - 16) = 9$ m. Khác với 5 m, nên ý c) <strong>Sai</strong>.</p><p class=\"text-base leading-relaxed my-2\"><strong>d)</strong> Công của lực kéo (cùng chiều chuyển động): $A = F \\cdot s$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $A = 24000 \\cdot 25 = 600000$ J. Ý d) <strong>Đúng</strong>.</p>","statements":[{"text":"Lực kéo của tháng máy có độ lớn 2400 N.","answer":false},{"text":"Quãng đường đi của thang máy trong 5 giây đầu tiên là 25 m.","answer":true},{"text":"Trong giây thứ 5 thang máy đi được 5 m.","answer":false},{"text":"Công của động cơ thang máy trong 5 giây đầu tiên là 600000 J.","answer":true}]}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một cần cẩu nâng một vật nặng khối lượng 5 tấn. Lấy g = 10 m/s$^{2}$.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\"><b>Tóm tắt:</b> $m = 5$ tấn $= 5000$ kg, $g = 10$ m/s$^2$. Trọng lượng của vật: $P = mg = 5000 \\cdot 10 = 50000$ N.</p><p class=\"text-base leading-relaxed my-2\"><b>Chọn chiều dương hướng lên.</b> Vật chuyển động nhanh dần đều từ trạng thái nghỉ, theo định luật II Niu-tơn: $F - P = ma$.</p><p class=\"text-base leading-relaxed my-2\"><b>a)</b> Với $a = 0{,}5$ m/s$^2$:</p><p class=\"text-base leading-relaxed my-2\">$F = P + ma = 50000 + 5000 \\cdot 0{,}5 = 52500$ N.</p><p class=\"text-base leading-relaxed my-2\">Đề ghi $55000$ N, không khớp với $52500$ N. Kết luận: <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>b)</b> Quãng đường đi được sau thời gian $t$ (nhanh dần đều từ nghỉ): $s = \\dfrac{1}{2}at^2$.</p><p class=\"text-base leading-relaxed my-2\">Với $t = 5$ s: $s = \\dfrac{1}{2} \\cdot 0{,}5 \\cdot 5^2 = 6{,}25$ m, không phải $5$ m. Kết luận: <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>c)</b> Đề thiếu số giây. Giá trị $2{,}25$ m khớp với $t = 3$ s:</p><p class=\"text-base leading-relaxed my-2\">$s = \\dfrac{1}{2} \\cdot 0{,}5 \\cdot 3^2 = 2{,}25$ m. Kết luận: <b>Đúng</b> (với giả thiết $t = 3$ s).</p><p class=\"text-base leading-relaxed my-2\"><b>d)</b> Công của lực nâng sau $t = 3$ s: $A = F \\cdot s$ (lực và độ dời cùng hướng).</p><p class=\"text-base leading-relaxed my-2\">$A = 52500 \\cdot 2{,}25 = 118125$ J. Kết luận: <b>Đúng</b>.</p>","statements":[{"text":"Lực nâng của cần cẩu có độ lớn 55000 N khi cần cẩu chuyển động với gia tốc không đổi bằng 0,5 m/s$^{2}$.","answer":false},{"text":"Quãng đương của cần cẩu đi sau 5 giây là 5 m.","answer":false},{"text":"Quãng đường của cần cẩu đi được sau giây là 2,25 m.","answer":true},{"text":"Công của cần cầu thực hiện được sau 3 giây là 118125 J.","answer":true}]}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một người kéo một vật có 10kg trượt trên mặt phẳng ngang có hệ số ma sát $m$ = 0,2 bằng một sợi dây có phương hợp một góc 30° so với phương nằm ngang. Lực tác dụng lên dây bằng $\\overset{\\rightarrow}{F_{k}}$ vật trượt không vận tốc đầu với gia tốc 2 m/s$^{2}$, lấy g = 9,8 m/s$^{2}$.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\"><b>Chọn chiều dương</b> theo chiều chuyển động (sang phải). Vật chuyển động trên mặt phẳng ngang, áp dụng định luật II Newton: $\\vec{P}+\\vec{N}+\\vec{F_k}+\\vec{F_{ms}}=m\\vec{a}$.</p><p class=\"text-base leading-relaxed my-2\"><b>a)</b> Các lực tác dụng lên vật: trọng lực $\\vec{P}$, phản lực $\\vec{N}$, lực kéo $\\vec{F_k}$ và lực ma sát trượt $\\vec{F_{ms}}$. Ý a) <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>b)</b> Chiếu lên phương ngang và phương thẳng đứng:</p><p class=\"text-base leading-relaxed my-2\">Phương thẳng đứng: $N+F_k\\sin 30^\\circ=mg$, suy ra $N=mg-F_k\\sin 30^\\circ$.</p><p class=\"text-base leading-relaxed my-2\">Phương ngang: $F_k\\cos 30^\\circ-\\mu N=ma$.</p><p class=\"text-base leading-relaxed my-2\">Thay $N$: $F_k\\cos 30^\\circ-\\mu(mg-F_k\\sin 30^\\circ)=ma$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F_k(\\cos 30^\\circ+\\mu\\sin 30^\\circ)=ma+\\mu mg$.</p><p class=\"text-base leading-relaxed my-2\">Thay số ($mg=98$ N, $ma=20$ N): $F_k(0{,}866+0{,}1)=20+19{,}6=39{,}6$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F_k\\approx 40{,}99\\ \\text{N}\\approx 41\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Lực kéo khoảng 41 N, không phải 40 N. Ý b) <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>c)</b> Quãng đường đi được sau $t=5$ s (vật xuất phát từ trạng thái nghỉ):</p><p class=\"text-base leading-relaxed my-2\">$s=\\dfrac{1}{2}at^2=\\dfrac{1}{2}\\cdot 2\\cdot 5^2=25\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Ý c) <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>d)</b> Công của lực kéo:</p><p class=\"text-base leading-relaxed my-2\">$A=F_k\\,s\\cos 30^\\circ=40{,}99\\cdot 25\\cdot 0{,}866\\approx 887{,}5\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Ý d) <b>Đúng</b>.</p>","statements":[{"text":"Các lực tác dụng lên vật gồm trọng lực, lực kéo, lực ma sát và phản lực.","answer":true},{"text":"Lực kéo tác dụng lên vật có giá trị là 40 N.","answer":false},{"text":"Quãng đường đi được sau 5 giây là 25 m.","answer":true},{"text":"Công của lực kéo trong thời gian 5 giây kể từ khi bắt đầu chuyển động có giá trị xấp xĩ là $887,5 J.$","answer":true}]}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"short_answer","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một tế bào cơ trong cơ thể người có thể coi như một động cơ siêu nhỏ, khi con người hoạt động, tế bào sử dụng năng lượng hóa học để thực hiện công. Trong mỗi nhịp hoạt động, tế bào cơ có thể sinh một lực 1,5.10$^{-12}$ N để dịch chuyển 8 nm. Công mà tế bào cơ sinh ra trong mỗi nhịp hoạt động là $X.10^{-20}J.$ Giá trị của X là bao nhiêu?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực không đổi cùng phương chuyển động: $A = F \\cdot d$, với $F$ là lực và $d$ là quãng đường dịch chuyển (cùng phương với lực).</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $d = 8\\ \\text{nm} = 8.10^{-9}\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A = 1{,}5.10^{-12} \\cdot 8.10^{-9} = 12.10^{-21}\\ \\text{J} = 1{,}2.10^{-20}\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">So sánh với dạng $X.10^{-20}\\ \\text{J}$ ta có $X = 1{,}2$.</p>","answer":"1,2"}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"short_answer","form":"bai_tap","topic":"Động năng và định lí động năng","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một vật khối lượng 10 kg đang trượt với vận tốc 10 m/s thì đi vào mặt phẳng nằm ngang có hệ số ma sát $m.$ ông của lực ma sát đã thực hiện đến khi vật dừng lại có giá trị là bao nhiêu J?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Áp dụng định lí động năng: công của các lực tác dụng lên vật bằng độ biến thiên động năng của vật.</p><p class=\"text-base leading-relaxed my-2\">Vật chỉ chịu lực ma sát theo phương ngang (trọng lực và phản lực vuông góc với chuyển động nên không sinh công), nên công của lực ma sát chính là công tổng hợp: $A_{ms} = W_{d2} - W_{d1}$.</p><p class=\"text-base leading-relaxed my-2\">Động năng ban đầu: $W_{d1} = \\dfrac{1}{2}mv_0^2 = \\dfrac{1}{2}\\cdot 10\\cdot 10^2 = 500\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Khi vật dừng lại: $W_{d2} = 0$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A_{ms} = 0 - 500 = -500\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: công của lực ma sát đến khi vật dừng lại là $-500\\ \\text{J}$ (công cản, có độ lớn 500 J). Hệ số ma sát không ảnh hưởng đến kết quả này.</p>","answer":"-500"}$q$::jsonb, 136, $q$Động năng và định lí động năng$q$),
($q${"type":"short_answer","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một thang máy khối lượng 600 kg được kéo từ đáy hầm mỏ sâu 150 m lên mặt đất bằng lực căng T của một dây cáp quấn quanh trục một động cơ. Khi thang máy đi xuống thì lực tăng của dây cáp bằng 5400 N. Lấy g = 10 m/s$^{2}$. Muốn cho thang xuống đều thì hệ thống hãm phải thực hiện công bằng bao nhiêu kN?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\"><strong>Chọn chiều dương</strong> hướng lên trên. Thang máy chuyển động xuống đều nên gia tốc bằng 0.</p><p class=\"text-base leading-relaxed my-2\">Trọng lượng của thang máy: $P = mg = 600 \\cdot 10 = 6000\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Khi thang xuống đều, định luật II Newton cho hợp lực bằng 0. Gọi $F_h$ là lực hãm (hướng lên), lực căng dây $T = 5400\\ \\text{N}$ hướng lên:</p><p class=\"text-base leading-relaxed my-2\">$T + F_h - P = 0$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F_h = P - T = 6000 - 5400 = 600\\ \\text{N}$</p><p class=\"text-base leading-relaxed my-2\">Lực hãm hướng lên, còn thang đi xuống quãng đường $s = 150\\ \\text{m}$ nên công của lực hãm có giá trị âm:</p><p class=\"text-base leading-relaxed my-2\">$A_h = -F_h \\cdot s = -600 \\cdot 150 = -90000\\ \\text{J} = -90\\ \\text{kJ}$</p><p class=\"text-base leading-relaxed my-2\"><strong>Kết luận:</strong> Hệ thống hãm phải thực hiện công cản khoảng $90$ kJ (công $A_h = -90$ kJ), tức độ lớn là $90$ kJ.</p>","answer":"90"}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"short_answer","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Để đưa một kiện hàng lên cao h = 80 cm so với mặt sàn người ta dùng một xe nâng. Công tối thiểu mà xe đã thực hiện bằng 9,6 kJ. Khối lượng kiện hàng là bao nhiêu tấn?. Biết gia tốc trọng trường là g = 10 m/s$^{2}$.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Công tối thiểu để nâng kiện hàng đều lên độ cao $h$ bằng độ tăng thế năng trọng trường, vì động năng không đổi (nâng đều, vận tốc ban đầu và cuối bằng 0).</p><p class=\"text-base leading-relaxed my-2\">Công thức: $A_{min} = mgh$, suy ra $m = \\dfrac{A_{min}}{gh}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $h = 80\\text{ cm} = 0{,}8\\text{ m}$; $A_{min} = 9{,}6\\text{ kJ} = 9600\\text{ J}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow m = \\dfrac{9600}{10 \\cdot 0{,}8} = 1200\\text{ kg}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow m = 1200\\text{ kg} = 1{,}2\\text{ tấn}$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: khối lượng kiện hàng là $1{,}2$ tấn.</p>","answer":"1,2"}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"short_answer","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Cho một vật có khối lượng 2 kg rơi tự do. Lấy $g=10 m/s^{2}.$ Công của trọng lực trong giây thứ năm là bao nhiêu J?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Vật rơi tự do không vận tốc đầu, chỉ chịu tác dụng của trọng lực. Chọn chiều dương hướng xuống.</p><p class=\"text-base leading-relaxed my-2\">Quãng đường vật rơi sau $t$ giây: $s(t)=\\dfrac{1}{2}gt^{2}$.</p><p class=\"text-base leading-relaxed my-2\">Quãng đường trong giây thứ năm là hiệu quãng đường rơi trong 5 giây và trong 4 giây:</p><p class=\"text-base leading-relaxed my-2\">$\\Delta s_5 = s(5)-s(4)=\\dfrac{1}{2}g(5^{2}-4^{2})$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\Delta s_5=\\dfrac{1}{2}\\cdot 10\\cdot(25-16)=45\\ \\text{m}$</p><p class=\"text-base leading-relaxed my-2\">Công của trọng lực trong giây thứ năm (trọng lực cùng chiều chuyển động):</p><p class=\"text-base leading-relaxed my-2\">$A=P\\cdot \\Delta s_5=mg\\cdot\\Delta s_5$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A=2\\cdot 10\\cdot 45=900\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\"><b>Kết luận:</b> Công của trọng lực trong giây thứ năm là $900$ J.</p>","answer":"900"}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"short_answer","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Công của trọng lực trong 2 giây cuối khi vật có khối lượng 8 kg được thả rơi từ độ cao 180 m là bao nhiêu kJ? Lấy g = 10 m/s$^{2}$.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Vật rơi tự do từ độ cao $h = 180$ m với $g = 10$ m/s$^2$, bỏ qua sức cản không khí. Chọn chiều dương hướng xuống.</p><p class=\"text-base leading-relaxed my-2\">Thời gian rơi cả quãng đường: $h = \\dfrac{1}{2}gt^2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow t = \\sqrt{\\dfrac{2h}{g}} = \\sqrt{\\dfrac{2 \\cdot 180}{10}} = 6$ s</p><p class=\"text-base leading-relaxed my-2\">Quãng đường vật rơi trong $4$ s đầu: $h_1 = \\dfrac{1}{2}g t_1^2 = \\dfrac{1}{2} \\cdot 10 \\cdot 4^2 = 80$ m</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Quãng đường rơi trong $2$ s cuối: $\\Delta h = h - h_1 = 180 - 80 = 100$ m</p><p class=\"text-base leading-relaxed my-2\">Công của trọng lực (trọng lực sinh công dương khi vật đi xuống): $A = P\\cdot\\Delta h = mg\\Delta h$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A = 8 \\cdot 10 \\cdot 100 = 8000$ J $= 8$ kJ</p><p class=\"text-base leading-relaxed my-2\">Kết luận: công của trọng lực trong 2 giây cuối là $8$ kJ.</p>","answer":"8"}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"short_answer","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một vật có khối lượng 2 kg rơi tự do từ độ cao h không vận tốc đầu, lấy g = 9,8 m/s$^{2}$, sau thời gian 2s vật chưa chạm đất. Tính công của trọng lực xấp xĩ bằng bao nhiêu J? (kết quả làm tròn đến phần nguyên).</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Vật rơi tự do không vận tốc đầu nên quãng đường đi được sau thời gian $t$ là $s = \\dfrac{1}{2}gt^2$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $g = 9{,}8\\ \\text{m/s}^2$, $t = 2\\ \\text{s}$: $s = \\dfrac{1}{2}\\cdot 9{,}8\\cdot 2^2 = 19{,}6\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Công của trọng lực: $A = P\\cdot s = mg\\cdot s$ (trọng lực cùng chiều chuyển động nên công dương).</p><p class=\"text-base leading-relaxed my-2\">Thay số với $m = 2\\ \\text{kg}$: $A = 2\\cdot 9{,}8\\cdot 19{,}6 = 384{,}16\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Làm tròn đến phần nguyên: $A \\approx 384\\ \\text{J}$.</p>","answer":"384"}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"short_answer","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một người nhấc một vật có khối lượng 5kg lên độ cao 1,2 m rồi mang đi ngang một đoạn 50 m. Tìm công tổng cộng mà người này đã thực hiện theo đơn vị J. Lấy gia tốc trọng trường là $g=10 m/s^{2}$</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Khi nhấc vật lên độ cao $h$ theo phương thẳng đứng, lực nâng của người cân bằng với trọng lực $P=mg$ và có phương song song với độ dịch chuyển, nên công của người là:</p><p class=\"text-base leading-relaxed my-2\">$A_1 = mgh$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A_1 = 5 \\cdot 10 \\cdot 1{,}2 = 60\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\">Khi mang vật đi ngang một đoạn 50 m, phương của lực nâng (thẳng đứng) vuông góc với phương dịch chuyển (nằm ngang), nên công thực hiện bằng 0:</p><p class=\"text-base leading-relaxed my-2\">$A_2 = F \\cdot s \\cdot \\cos 90^\\circ = 0$</p><p class=\"text-base leading-relaxed my-2\">Công tổng cộng người thực hiện là:</p><p class=\"text-base leading-relaxed my-2\">$A = A_1 + A_2 = 60 + 0 = 60\\ \\text{J}$</p>","answer":"60"}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"short_answer","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Sau khi cất cánh 0,5 phút, trực thăng có khối lượng m = 6 tấn, lên đến độ cao h. Coi chuyển động là nhanh dần đều và lấy gia tốc trọng trường là g = 10 m/s$^{2}$. Công của động cơ trực thăng thực hiện bằng 64,8.10$^{6}$ J. Tìm độ cao h theo đơn vị m.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Trực thăng chuyển động thẳng đứng nhanh dần đều từ trạng thái nghỉ, $t = 0,5$ phút $= 30$ s, $m = 6000$ kg. Chọn chiều dương hướng lên.</p><p class=\"text-base leading-relaxed my-2\">Độ cao: $h = \\dfrac{1}{2}at^2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow a = \\dfrac{2h}{t^2} = \\dfrac{2h}{900}$</p><p class=\"text-base leading-relaxed my-2\">Định luật II Newton: $F - mg = ma$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F = m(g + a)$</p><p class=\"text-base leading-relaxed my-2\">Công của động cơ: $A = F h = m\\left(g + \\dfrac{2h}{t^2}\\right)h$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow 64{,}8.10^6 = 6000\\left(10 + \\dfrac{2h}{900}\\right)h$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow h^2 + 4500h - 4\\,860\\,000 = 0$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow h = \\dfrac{-4500 + 6300}{2} = 900$ m (nhận nghiệm dương).</p><p class=\"text-base leading-relaxed my-2\">Kiểm tra: $a = 2$ m/s², $F = 72000$ N, $A = 72000 \\cdot 900 = 64{,}8.10^6$ J ✓.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: $h = 900$ m.</p>","answer":"900"}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"short_answer","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Cho một máy bay lên thẳng có khối lượng 5.10$^{3}$ kg sau thời gian 2 phút máy bay lên được độ cao là 1440 m. Lấy g = 10m/s$^{2}$. Tính công của động cơ trong trường hợp coi chuyển động của máy bay là chuyển động thẳng nhanh dần đều theo đơn vị MJ. (kết quả làm tròn đến một chữ số thập phân sau dấu phẩy).</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Chọn chiều dương hướng lên. Máy bay chuyển động thẳng nhanh dần đều từ trạng thái đứng yên, với quãng đường $h = 1440$ m trong thời gian $t = 120$ s.</p><p class=\"text-base leading-relaxed my-2\">Gia tốc của máy bay: $h = \\dfrac{1}{2}at^2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow a = \\dfrac{2h}{t^2} = \\dfrac{2 \\cdot 1440}{120^2} = 0{,}2\\ \\text{m/s}^2$.</p><p class=\"text-base leading-relaxed my-2\">Theo định luật II Niu-tơn, lực nâng của động cơ $F$ thỏa mãn: $F - mg = ma$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F = m(g + a)$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $F = 5.10^3 \\cdot (10 + 0{,}2) = 51000$ N.</p><p class=\"text-base leading-relaxed my-2\">Công của động cơ (lực $F$ cùng hướng với độ dời): $A = F \\cdot h$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $A = 51000 \\cdot 1440 = 73\\,440\\,000$ J $= 73{,}44$ MJ $\\approx 73{,}4$ MJ.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: công của động cơ khoảng $73{,}4$ MJ.</p>","answer":"73.4"}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"short_answer","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một thang máy có khối lượng 1 tấn chuyên động nhanh dần đều lên cao với gia tốc 2 m/s. Lấy g = 10 m/s$^{2}$. Tính công mà động cơ thang máy đã thực hiện trong 5 s đầu theo đơn vị kJ.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Đề ghi \"2 m/s\" thiếu mũ nên được hiểu là 2 m/s²; thang máy xuất phát từ trạng thái nghỉ; 1 tấn = 1000 kg.</p><p class=\"text-base leading-relaxed my-2\">Áp dụng định luật II Newton cho thang máy, chọn chiều dương hướng lên: $F - mg = ma$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F = m(g+a) = 1000\\cdot(10+2) = 12000$ N.</p><p class=\"text-base leading-relaxed my-2\">Quãng đường đi được trong 5 s đầu: $s = \\dfrac{1}{2}at^2 = \\dfrac{1}{2}\\cdot 2\\cdot 5^2 = 25$ m.</p><p class=\"text-base leading-relaxed my-2\">Lực kéo cùng hướng với độ dời nên công của động cơ là $A = Fs$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A = 12000\\cdot 25 = 300000$ J $= 300$ kJ.</p>","answer":"300"}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"short_answer","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một người kéo một thùng hàng khối lượng 80 kg trượt trên sàn nhà bằng một dây có phương hợp góc $a=30^{0 }$^ ^so với phương nằm ngang. Biết lực tác dụng lên dây bằng 150 N. Tính công của lực đó khi hòm trượt đi được 29 m theo đơn vị kJ. (kết quả làm tròn đến hai chữ số thập phân sau dấu phẩy).</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực không đổi tác dụng lên vật khi vật dịch chuyển thẳng: $A = F\\cdot s\\cdot\\cos\\alpha$, trong đó $\\alpha$ là góc giữa lực và phương dịch chuyển.</p><p class=\"text-base leading-relaxed my-2\">Ở đây lực kéo $F = 150\\ \\text{N}$ hợp với phương ngang góc $\\alpha = 30^\\circ$, và quãng đường $s = 29\\ \\text{m}$ (theo phương ngang, cùng phương chuyển động của thùng).</p><p class=\"text-base leading-relaxed my-2\">Thay số: $A = 150 \\cdot 29 \\cdot \\cos 30^\\circ = 4350 \\cdot \\dfrac{\\sqrt{3}}{2} \\approx 3767{,}2\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A \\approx 3{,}77\\ \\text{kJ}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: công của lực kéo khi thùng trượt được 29 m là khoảng $3{,}77\\ \\text{kJ}$.</p>","answer":"3,77"}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"short_answer","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một người kéo một thùng hàng khối lượng 150 kg trượt trên sàn nhà bằng một sợi dây có phương hợp góc 30$^{0}$ so với phương thẳng đứng. Biết lực tác dụng lên dây bằng 200 N. Tính công của lực đó khi thùng hàng trượt đi được 2 m theo đơn vị J.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực $\\vec{F}$ được tính theo công thức: $A = F\\,s\\cos\\alpha$, trong đó $\\alpha$ là góc giữa lực $\\vec{F}$ và phương chuyển động (phương ngang).</p><p class=\"text-base leading-relaxed my-2\">Dây hợp với phương thẳng đứng một góc $30^\\circ$ nên hợp với phương ngang một góc: $\\alpha = 90^\\circ - 30^\\circ = 60^\\circ$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $F = 200\\ \\text{N}$, $s = 2\\ \\text{m}$:</p><p class=\"text-base leading-relaxed my-2\">$A = 200 \\cdot 2 \\cdot \\cos 60^\\circ = 200\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: công của lực kéo là $A = 200\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">(Khối lượng 150 kg không ảnh hưởng đến công của lực kéo trong bài này.)</p>","answer":"200"}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"short_answer","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một vật có khối lượng 3 kg được kéo lên trên mặt phẳng nghiêng một góc 30° so với phương ngang bởi một lực không đổi 70 N dọc theo mặt phẳng nghiêng. Biết hệ số ma sát là 0,05, lấy g = 10 m/s$^{2}$. Tính tổng công của tất cả các lực tác dụng lên vật khi vật di chuyển được một quãng đường 2 m theo đơn vị J.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Các lực tác dụng: lực kéo $F$ (song song mặt phẳng nghiêng, hướng lên), trọng lực $P$, phản lực $N$, lực ma sát $F_{ms}$. Chọn chiều dương là chiều chuyển động (lên dốc). Tổng công bằng tổng đại số công của các lực.</p><p class=\"text-base leading-relaxed my-2\">$N = mg\\cos30° = 3\\cdot10\\cdot\\frac{\\sqrt3}{2}\\approx 25{,}98$ N</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F_{ms}=\\mu N = 0{,}05\\cdot25{,}98\\approx 1{,}30$ N</p><p class=\"text-base leading-relaxed my-2\">Công lực kéo: $A_F = Fs = 70\\cdot2 = 140$ J</p><p class=\"text-base leading-relaxed my-2\">Công trọng lực: $A_P = -mg\\sin30°\\cdot s = -15\\cdot2 = -30$ J</p><p class=\"text-base leading-relaxed my-2\">Công phản lực: $A_N = 0$ (vuông góc với độ dời)</p><p class=\"text-base leading-relaxed my-2\">Công lực ma sát: $A_{ms} = -F_{ms}s \\approx -1{,}30\\cdot2\\approx -2{,}6$ J</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A = 140 - 30 + 0 - 2{,}6 \\approx 107{,}4$ J</p><p class=\"text-base leading-relaxed my-2\">Kết luận: tổng công của các lực tác dụng lên vật khoảng $107{,}4$ J.</p>","answer":"107,4"}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"short_answer","form":"bai_tap","topic":"Biến thiên cơ năng khi có ma sát","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một vật có khối lượng 1,5 kg đang chuyển động với vận tốc 2 m/s thì trượt xuống một con dốc nghiêng một góc 30$^{0}$ so với mặt phẳng ngang. Khi đến chân dốc, vật đạt vận tốc 6 m/s. Biết dốc dài 8m. Lấy g = 10 m/s$^{2}$. Tính công của lực ma sát theo đơn vị J.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Chọn gốc thế năng tại chân dốc. Áp dụng định lí động năng cho vật trượt trên dốc: tổng công của trọng lực và lực ma sát bằng độ biến thiên động năng.</p><p class=\"text-base leading-relaxed my-2\">$W_P + A_{ms} = \\dfrac{1}{2}mv_2^2 - \\dfrac{1}{2}mv_1^2$</p><p class=\"text-base leading-relaxed my-2\">Độ cao giảm của vật khi trượt hết dốc dài $\\ell = 8$ m, nghiêng $30^{\\circ}$:</p><p class=\"text-base leading-relaxed my-2\">$h = \\ell \\sin 30^{\\circ} = 8 \\cdot 0{,}5 = 4$ m</p><p class=\"text-base leading-relaxed my-2\">Công của trọng lực:</p><p class=\"text-base leading-relaxed my-2\">$W_P = mgh = 1{,}5 \\cdot 10 \\cdot 4 = 60$ J</p><p class=\"text-base leading-relaxed my-2\">Độ biến thiên động năng:</p><p class=\"text-base leading-relaxed my-2\">$\\Delta W_d = \\dfrac{1}{2}\\cdot 1{,}5\\,(6^2 - 2^2) = 0{,}75 \\cdot 32 = 24$ J</p><p class=\"text-base leading-relaxed my-2\">Công của lực ma sát:</p><p class=\"text-base leading-relaxed my-2\">$A_{ms} = \\Delta W_d - W_P = 24 - 60 = -36$ J</p><p class=\"text-base leading-relaxed my-2\">Kết luận: công của lực ma sát bằng $-36$ J (lực ma sát sinh công cản, lấy mất 36 J cơ năng).</p>","answer":"-36"}$q$::jsonb, 139, $q$Biến thiên cơ năng khi có ma sát$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính công suất trung bình và công suất tức thời","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Gọi $A$ là công mà một lực đã sinh ra trong thời gian $ t$ để vật đi được quãng đường $ s.$ Công suất là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Công suất là đại lượng đo bằng tỉ số giữa công thực hiện và thời gian thực hiện công đó.</p><p class=\"text-base leading-relaxed my-2\">Công thức: $P=\\dfrac{A}{t}$, trong đó $A$ là công (J), $t$ là thời gian (s), $P$ là công suất (W).</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là A.</p>","options":["$P=\\frac{A}{t}.$","$P=\\frac{t}{A}.$","$P=\\frac{A}{s}.$","$P=\\frac{s}{A}.$"],"answer":0}$q$::jsonb, 134, $q$Tính công suất trung bình và công suất tức thời$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính hiệu suất của máy và động cơ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hiệu suất của một quá trình chuyển hóa công được kí hiệu là H. Vậy H luôn có giá trị</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hiệu suất của quá trình chuyển hóa công được định nghĩa:</p><p class=\"text-base leading-relaxed my-2\">$H = \\frac{A_{\\text{có ích}}}{A_{\\text{toàn phần}}} \\cdot 100\\%$ (hoặc $H = \\frac{A_{\\text{có ích}}}{A_{\\text{toàn phần}}}$ khi tính theo tỉ số).</p><p class=\"text-base leading-relaxed my-2\">Theo định luật bảo toàn năng lượng, công có ích chỉ là một phần của công toàn phần; phần còn lại bị hao phí (ví dụ do ma sát, tỏa nhiệt). Do đó:</p><p class=\"text-base leading-relaxed my-2\">$0 \\lt A_{\\text{có ích}} \\le A_{\\text{toàn phần}}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$0 \\lt H \\le 1$.</p><p class=\"text-base leading-relaxed my-2\">$H = 1$ chỉ đạt được trong trường hợp lý tưởng không có hao phí. Vậy H luôn thỏa mãn $0 \\lt H \\le 1$.</p><p class=\"text-base leading-relaxed my-2\">Đáp án đúng: D.</p>","options":["\\> 1.","= 1.","\\< 1.","$0<H\\pounds1.$"],"answer":3}$q$::jsonb, 140, $q$Tính hiệu suất của máy và động cơ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính hiệu suất của máy và động cơ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây là <strong>sai</strong> khi nói về hiệu suất?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hiệu suất của máy được xác định bằng tỉ số giữa công có ích và công toàn phần:</p><p class=\"text-base leading-relaxed my-2\">$H = \\dfrac{A_{\\text{ci}}}{A_{\\text{tp}}}$</p><p class=\"text-base leading-relaxed my-2\">Vì công toàn phần bao gồm công có ích và công hao phí, nên $A_{\\text{tp}} = A_{\\text{ci}} + A_{\\text{hp}}$ với $A_{\\text{hp}} \\gt 0$ (không thể bằng 0 trong thực tế). Do đó $A_{\\text{ci}} \\lt A_{\\text{tp}}$, suy ra $H \\lt 1$.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Đúng, vì hiệu suất là tỉ lệ giữa công có ích và công toàn phần.</p><p class=\"text-base leading-relaxed my-2\">B. Sai, vì hiệu suất không tính bằng hiệu số mà bằng thương số $\\dfrac{A_{\\text{ci}}}{A_{\\text{tp}}}$.</p><p class=\"text-base leading-relaxed my-2\">C. Đúng, vì đây chính là cách tính thương số giữa công có ích và công toàn phần.</p><p class=\"text-base leading-relaxed my-2\">D. Đúng, vì $H \\lt 1$ như đã chứng minh ở trên.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: phát biểu sai là phương án <b>B</b>.</p>","options":["Hiệu suất cho biết tỉ lệ giữa công có ích và công toàn phần do máy sinh ra khi hoạt động.","Hiệu suất được tính bằng hiệu số giữa công có ích và công toàn phần.","Hiệu suất được tính bằng thương số giữa công có ích và công toàn phần.","Hiệu suất có giá trị luôn nhỏ hơn 1."],"answer":1}$q$::jsonb, 140, $q$Tính hiệu suất của máy và động cơ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Hao phí năng lượng và cách giảm hao phí","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Khi quạt điện hoạt động thì phần năng lượng hao phí là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Quạt điện biến đổi điện năng thành cơ năng để làm cánh quạt quay, tạo ra gió.</p><p class=\"text-base leading-relaxed my-2\">Trong quá trình này, một phần điện năng không chuyển thành cơ năng có ích mà bị hao phí dưới dạng nhiệt năng, do dòng điện chạy qua các cuộn dây gây tỏa nhiệt (hiệu ứng Joule) và do ma sát ở trục quay, ổ bi.</p><p class=\"text-base leading-relaxed my-2\">Vậy phần năng lượng hao phí là nhiệt năng.</p>","options":["điện năng.","cơ năng.","nhiệt năng.","hóa năng."],"answer":2}$q$::jsonb, 141, $q$Hao phí năng lượng và cách giảm hao phí$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Công suất của động cơ, máy kéo","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Đơn vị đo công suất ở nước Anh được kí hiệu là $.$ Nếu một chiếc máy có ghi $50 HP$ thì công suất của máy là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Đơn vị mã lực (horsepower, kí hiệu HP) là đơn vị đo công suất dùng ở nước Anh. Quy đổi: $1\\,HP \\approx 745{,}7\\,W = 0{,}7457\\,kW$.</p><p class=\"text-base leading-relaxed my-2\">Công suất của máy: $P = 50\\,HP$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow P = 50 \\cdot 0{,}7457\\,kW \\approx 37{,}3\\,kW$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: công suất của máy là $37{,}3\\,kW$, chọn đáp án B.</p>","options":["$36,8 kW.$","$37,3 kW.$","$50 kW.$","$50 W.$"],"answer":1}$q$::jsonb, 135, $q$Công suất của động cơ, máy kéo$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một vật khối lượng m được kéo chuyển động thẳng đều trên sàn bằng một lực F = 20 N hợp với phương ngang góc $30{^\\circ},$ khi vật di chuyển 2 m hết thời gian 4 s.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Vật chuyển động thẳng đều, lực kéo $F$ không đổi hợp với phương dịch chuyển góc $\\alpha = 30^\\circ$ nên công của lực kéo: $A = F s\\cos\\alpha$.</p><p class=\"text-base leading-relaxed my-2\">Với $s = 2$ m: $A = 20\\cdot 2\\cdot\\cos 30^\\circ = 20\\sqrt3 \\approx 34{,}64$ J.</p><p class=\"text-base leading-relaxed my-2\">a) Công trong 4 s là $34{,}64$ J, không phải $20$ J. Sai.</p><p class=\"text-base leading-relaxed my-2\">b) $P = \\dfrac{A}{t} = \\dfrac{34{,}64}{4}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow P \\approx 8{,}66$ W, không phải $3$ W. Sai.</p><p class=\"text-base leading-relaxed my-2\">c) Với $s = 10$ m: $A = 20\\cdot 10\\cdot\\cos 30^\\circ$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A \\approx 173{,}2$ J, không phải $3$ J. Sai.</p><p class=\"text-base leading-relaxed my-2\">d) $P = \\dfrac{173{,}2}{15}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow P \\approx 11{,}5$ W, không phải $3$ W. Sai.</p>","statements":[{"text":"Công của lực kéo trong 4 s là 20 J.","answer":false},{"text":"Công suất của lực kéo trong 4s là $3 W.$","answer":false},{"text":"Nếu vật di chuyển được 10 m thì công của lực kéo là $3 J.$","answer":false},{"text":"Vật di chuyển 10 m hết 15 s thì công suất của lực kéo là $3 W.$","answer":false}]}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Công của lực và trường hợp lực xiên góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một vật khối lượng m = 10 kg được kéo chuyển động thẳng nhanh dần đều trên sàn nhẵn không ma sát bằng một lực$F = 5 N$ theo phương ngang từ trạng thái nghỉ.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Chọn chiều dương cùng chiều chuyển động. Vật chuyển động thẳng nhanh dần đều từ trạng thái nghỉ, sàn nhẵn nên lực kéo là hợp lực. Áp dụng định luật II Newton: $F = ma$.</p><p class=\"text-base leading-relaxed my-2\">a) Gia tốc của vật: $a = \\dfrac{F}{m} = \\dfrac{5}{10} = 0{,}5\\ \\text{m/s}^2$. Ý này đúng.</p><p class=\"text-base leading-relaxed my-2\">b) Quãng đường đi được trong $t = 4$ s với $v_0 = 0$: $s = \\dfrac{1}{2}at^2 = \\dfrac{1}{2}\\cdot 0{,}5\\cdot 4^2 = 4\\ \\text{m}$. Ý này sai, vì đề ghi 5 m.</p><p class=\"text-base leading-relaxed my-2\">c) Công của lực kéo: $A = Fs = 5\\cdot 4 = 20\\ \\text{J}$. Ý này đúng.</p><p class=\"text-base leading-relaxed my-2\">d) Công suất trung bình: $\\bar{P} = \\dfrac{A}{t} = \\dfrac{20}{4} = 5\\ \\text{W}$. Công suất tức thời tại $t = 4$ s: $v = at = 2\\ \\text{m/s}$, $P = Fv = 10\\ \\text{W}$. Cả hai giá trị đều không bằng 4 W, nên ý này sai.</p>","statements":[{"text":"Gia tốc của vật là $.$","answer":true},{"text":"Quãng đường vật đi được trong 4 giây là 5 m.","answer":false},{"text":"Công của lực kéo thực hiện được là 20 J.","answer":true},{"text":"Công suất của lực kéo đó là 4 W.","answer":false}]}$q$::jsonb, 132, $q$Công của lực và trường hợp lực xiên góc$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Tính công suất trung bình và công suất tức thời","difficulty":"kho","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một ô tô, khối lượng là 4 tấn đang chuyển động đều trên con đường thẳng nằm ngang với vận tốc 10 m/s, với công suất của động cơ ô tô là 20 kW. Sau đó ô tộ tăng tốc, chuyển động nhanh dần đều và sau khi đi thêm được quãng đường 250 m vận tốc ô tô tăng lên đến 54 km/h. Lấy g = 10 m/s$^{2}$.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\"><b>Bước 1: Lực cản.</b> Khi ô tô chuyển động đều, lực kéo cân bằng lực cản: $F_{k0}=f$. Công suất $P=F_{k0}v_0$ nên $f=\\dfrac{P}{v_0}=\\dfrac{20000}{10}=2000\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\"><b>Bước 2: Gia tốc (ý a).</b> Đổi $v=54\\ \\text{km/h}=15\\ \\text{m/s}$. Áp dụng công thức độc lập thời gian cho chuyển động nhanh dần đều:</p><p class=\"text-base leading-relaxed my-2\">$v^2-v_0^2=2as$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow a=\\dfrac{v^2-v_0^2}{2s}=\\dfrac{15^2-10^2}{2\\cdot 250}=0{,}25\\ \\text{m/s}^2$</p><p class=\"text-base leading-relaxed my-2\">Ý a) <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>Bước 3: Lực kéo khi tăng tốc.</b> Định luật II Newton theo chiều chuyển động: $F_k-f=ma$.</p><p class=\"text-base leading-relaxed my-2\">$F_k=f+ma=2000+4000\\cdot 0{,}25=3000\\ \\text{N}$</p><p class=\"text-base leading-relaxed my-2\"><b>Bước 4: Công suất tức thời cuối quãng đường (ý b).</b></p><p class=\"text-base leading-relaxed my-2\">$P=F_k v=3000\\cdot 15=45000\\ \\text{W}$</p><p class=\"text-base leading-relaxed my-2\">Ý b) nêu $4500$ W nên <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>Bước 5: Vận tốc trung bình (ý c).</b> Với chuyển động nhanh dần đều:</p><p class=\"text-base leading-relaxed my-2\">$\\bar{v}=\\dfrac{v_0+v}{2}=\\dfrac{10+15}{2}=12{,}5\\ \\text{m/s}$</p><p class=\"text-base leading-relaxed my-2\">Ý c) <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>Bước 6: Công suất trung bình (ý d).</b> Thời gian chuyển động: $t=\\dfrac{v-v_0}{a}=\\dfrac{15-10}{0{,}25}=20\\ \\text{s}$.</p><p class=\"text-base leading-relaxed my-2\">Công của lực kéo: $A=F_k s=3000\\cdot 250=750000\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\">Công suất trung bình: $\\bar{P}=\\dfrac{A}{t}=\\dfrac{750000}{20}=37500\\ \\text{W}$</p><p class=\"text-base leading-relaxed my-2\">Kiểm tra: $\\bar{P}=F_k\\bar{v}=3000\\cdot 12{,}5=37500\\ \\text{W}$. Ý d) nêu $357000$ W nên <b>Sai</b>.</p>","statements":[{"text":"Gia tốc chuyển động của ô tô là $0,25 m/s^{2}.$","answer":true},{"text":"Công suất tức thời của động cơ ở cuối quãng đường là 4500 W.","answer":false},{"text":"Vận tốc trung bình của ô tô trên quãng đường là 12,5 m/s.","answer":true},{"text":"Công suất trung bình của động cơ ô tô trên quãng đường là 357000 W.","answer":false}]}$q$::jsonb, 134, $q$Tính công suất trung bình và công suất tức thời$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Công suất của động cơ, máy kéo","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một ô tô khối lượng 1 tấn đang hoạt động với công suất 5 kW và chuyển động thẳng đều với vận tốc $54 km/h$ thì lên dốc. Hỏi động cơ ô tô phải hoạt động với công suất bằng bao nhiêu để có thể lên dốc với tốc độ như cũ? Hệ số ma sát giữa bánh xe và mặt đường không đổi, dốc nghiêng góc$0\\$ so với mặt đường nằm ngang và $2 .$</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $m = 1000\\ \\text{kg}$, $v = 54\\ \\text{km/h} = 15\\ \\text{m/s}$, $P_1 = 5000\\ \\text{W}$.</p><p class=\"text-base leading-relaxed my-2\">Trên đường nằm ngang, ô tô chuyển động thẳng đều nên lực kéo của động cơ cân bằng với lực ma sát. Công suất: $P = F.v$ nên lực kéo (cũng là lực ma sát) là $F_{ms} = \\dfrac{P_1}{v} = \\dfrac{5000}{15} \\approx 333\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">a) Sai. Lực ma sát là $333\\ \\text{N}$, không phải $1000\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">b) Đúng. Trên mặt phẳng ngang, $F_{ms} = \\mu mg$ suy ra $\\mu = \\dfrac{F_{ms}}{mg} = \\dfrac{333}{1000.10} \\approx \\dfrac{1}{30}$.</p><p class=\"text-base leading-relaxed my-2\">c) Đúng. Chọn chiều dương theo chiều chuyển động (lên dốc). Khi lên dốc đều, lực kéo cân bằng với thành phần trọng lực dọc dốc và lực ma sát: $F = mg\\sin\\alpha + \\mu mg\\cos\\alpha$. Với $\\sin\\alpha = 0{,}04$ (giả thiết, xem ghi chú), $\\cos\\alpha \\approx 0{,}9992$:</p><p class=\"text-base leading-relaxed my-2\">$F = 1000.10.0{,}04 + 333.0{,}9992 \\approx 400 + 333 = 733\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">d) Sai. Công suất cần thiết: $P = F.v = 733.15 \\approx 10995\\ \\text{W}$, không phải $10599\\ \\text{W}$.</p>","statements":[{"text":"Lực ma sát giũa bánh xe và mặt đường là 1000 N.","answer":false},{"text":"Hệ số ma sát giữa bánh xe và mặt đường là $\\frac{1}{30}$.","answer":true},{"text":"Lực của động cơ khi lên dốc là 733 N.","answer":true},{"text":"Công suất của ô tô khi lên dốc với tốc độ như cũ là 10599 W.","answer":false}]}$q$::jsonb, 135, $q$Công suất của động cơ, máy kéo$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Tính hiệu suất của máy và động cơ","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một máy bơm, bơm nước lên cao 10 m với lưu lượng 500 lít/phút. Hiệu suất của máy bơm là 80%. Biết khối lượng riêng của nước $D=1000 kg/m^{3}.$</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Đổi lưu lượng: $500$ lít/phút $=0{,}5\\ \\text{m}^3$/phút. Trong $1$ giây, thể tích nước bơm được là $V=\\dfrac{0{,}5}{60}=\\dfrac{1}{120}\\ \\text{m}^3$.</p><p class=\"text-base leading-relaxed my-2\">Khối lượng nước bơm trong $1$ giây: $m=D\\cdot V=1000\\cdot\\dfrac{1}{120}\\approx 8{,}33\\ \\text{kg}$.</p><p class=\"text-base leading-relaxed my-2\">Công có ích (nâng nước lên độ cao $h$, bỏ qua động năng của nước): $A_{\\text{ích}}=m\\,g\\,h$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $g=10\\ \\text{m/s}^2$, $h=10\\ \\text{m}$: $A_{\\text{ích}}=8{,}33\\cdot 10\\cdot 10\\approx 833{,}3\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Ý a) <b>Đúng</b> (hiểu là công cần thiết để nâng nước trong $1$ giây).</p><p class=\"text-base leading-relaxed my-2\">Hiệu suất: $H=\\dfrac{A_{\\text{ích}}}{A}$, suy ra công thực tế của động cơ trong $1$ giây: $A=\\dfrac{A_{\\text{ích}}}{H}=\\dfrac{833{,}3}{0{,}8}\\approx 1041{,}7\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Ý b) <b>Sai</b> (công thực tế là $1041{,}7$ J, không phải $1401{,}6$ J).</p><p class=\"text-base leading-relaxed my-2\">Công suất của máy bơm: $P=\\dfrac{A}{t}=\\dfrac{1041{,}7}{1}\\approx 1041{,}7\\ \\text{W}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Ý c) <b>Đúng</b> (khớp với $1041{,}6$ W sai số làm tròn).</p><p class=\"text-base leading-relaxed my-2\">Thời gian $t=30$ phút $=1800$ s. Công trong $30$ phút: $A_{30}=P\\cdot t=1041{,}7\\cdot 1800\\approx 1{,}875\\cdot 10^{6}\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Ý d) <b>Sai</b> (giá trị đúng khoảng $1875000$ J, không phải $1874268$ J).</p>","statements":[{"text":"Công cần thiết của động cơ máy bơm là 833,3 J.","answer":true},{"text":"Công thực tế của động cơ máy bơm là 1401,6 J.","answer":false},{"text":"Công suất của máy bơm trong 1 giây là 1041,6 W.","answer":true},{"text":"Công của máy bơm trong 30 phút là 1874268 J.","answer":false}]}$q$::jsonb, 140, $q$Tính hiệu suất của máy và động cơ$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Tính hiệu suất của máy và động cơ","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một cần trục nâng đều một kiện hàng khối lượng 1 tấn lên cao 10 m trong thời gian 30 s. Biết hiệu suất của động cơ là 60%. Cho g = 10 m/s$^{2}$</p>","explanation":"<p class=\"text-base leading-relaxed my-2\"><strong>Tóm tắt:</strong> $m = 1$ tấn $= 1000$ kg, $h = 10$ m, $t = 30$ s, $H = 60\\%$, $g = 10$ m/s$^2$.</p><p class=\"text-base leading-relaxed my-2\"><strong>a)</strong> Công của lực nâng (công có ích) bằng độ tăng thế năng của kiện hàng: $A_{i} = P\\cdot h = mgh$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $A_{i} = 1000 \\cdot 10 \\cdot 10 = 10^{5}$ J.</p><p class=\"text-base leading-relaxed my-2\">Ý a) nêu $2.10^{5}$ J, nên <strong>Sai</strong>.</p><p class=\"text-base leading-relaxed my-2\"><strong>b)</strong> Hiệu suất: $H = \\dfrac{A_{i}}{A_{tp}}$, suy ra công thực tế của động cơ là $A_{tp} = \\dfrac{A_{i}}{H}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $A_{tp} = \\dfrac{10^{5}}{0{,}6} \\approx 1{,}67\\cdot 10^{5}$ J.</p><p class=\"text-base leading-relaxed my-2\">Ý b) nêu 500000 J, nên <strong>Sai</strong>.</p><p class=\"text-base leading-relaxed my-2\"><strong>c)</strong> Công suất của động cơ: $\\mathcal{P} = \\dfrac{A_{tp}}{t}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $\\mathcal{P} = \\dfrac{1{,}67\\cdot 10^{5}}{30} \\approx 5555{,}6$ W $\\approx 5555{,}5$ W.</p><p class=\"text-base leading-relaxed my-2\">Ý c) <strong>Đúng</strong> (sai khác chỉ do làm tròn).</p><p class=\"text-base leading-relaxed my-2\"><strong>d)</strong> Công suất động cơ không đổi. Khi nâng khối lượng $2$ tấn lên $10$ m, công thực tế tăng gấp đôi: $A'_{tp} = 2A_{tp}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Thời gian nâng: $t' = \\dfrac{A'_{tp}}{\\mathcal{P}} = 2t = 2\\cdot 30 = 60$ s.</p><p class=\"text-base leading-relaxed my-2\">Ý d) <strong>Đúng</strong>.</p>","statements":[{"text":"Công của lực nâng là $2.10^{5} J.$","answer":false},{"text":"Công thực tế của động cơ là 500000 J.","answer":false},{"text":"Công suất của động cơ cần trục là 5555,5 W.","answer":true},{"text":"Nếu phải nâng đều một kiện hàng khối lượng 2 tấn lên cao 10 m thì thời gian nâng là 60 s.","answer":true}]}$q$::jsonb, 140, $q$Tính hiệu suất của máy và động cơ$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Tính công suất trung bình và công suất tức thời","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một người kéo đều thùng nước hết 16 s có khối lượng 12 kg từ giếng sâu 8 m. Lấy g = 10 m/s$^{2}$:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Trọng lượng của thùng nước: $P = mg = 12 \\cdot 10 = 120\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\"><b>a)</b> Thùng được kéo đều nên lực kéo cân bằng với trọng lượng: $F = P = 120\\ \\text{N}$. Công của người: $A = F \\cdot h = 120 \\cdot 8 = 960\\ \\text{J}$. Khẳng định <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>b)</b> Công suất: $\\mathcal{P} = \\dfrac{A}{t} = \\dfrac{960}{16} = 60\\ \\text{W}$, không phải $90\\ \\text{W}$. Khẳng định <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>c)</b> Thùng đi lên nhanh dần đều từ trạng thái đứng yên, quãng đường $h = 8\\ \\text{m}$ trong $t = 2\\ \\text{s}$:</p><p class=\"text-base leading-relaxed my-2\">$h = \\dfrac{1}{2}at^2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow 8 = \\dfrac{1}{2}a \\cdot 2^2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow a = 4\\ \\text{m/s}^2$.</p><p class=\"text-base leading-relaxed my-2\">Định luật II Newton (chiều dương hướng lên): $F' - P = ma$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F' = m(g + a) = 12 \\cdot 14 = 168\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Công: $A' = F' \\cdot h = 168 \\cdot 8 = 1344\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Công suất trung bình: $\\mathcal{P}' = \\dfrac{A'}{t} = \\dfrac{1344}{2} = 672\\ \\text{W}$, không phải $627\\ \\text{W}$. Khẳng định <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>d)</b> Lấy công có ích là công nâng thùng lên độ cao $h$ (960 J) và công toàn phần là công cần thiết trong trường hợp nhanh dần đều (1344 J):</p><p class=\"text-base leading-relaxed my-2\">$H = \\dfrac{A_{\\text{ích}}}{A_{\\text{tp}}} = \\dfrac{960}{1344} \\approx 0{,}714 = 71{,}4\\%$. Khẳng định <b>Đúng</b>.</p>","statements":[{"text":"Công của người khi kéo đều thùng nước là 960 J.","answer":true},{"text":"Công suất của người kéo là 90 W.","answer":false},{"text":"Nếu dung mày để kéo thùng nước nói trên đi lên nhanh dần đều và thời gian kéo mất 2 s thì công suất là 627 W.","answer":false},{"text":"Hiệu suất của máy là 71,4%.","answer":true}]}$q$::jsonb, 134, $q$Tính công suất trung bình và công suất tức thời$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Tính hiệu suất của máy và động cơ","difficulty":"kho","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một xe tải có khối lượng 2,5 tấn, bắt đầu chuyển động thẳng nhanh dần đều. Sau khi đi được quãng đường 144 m thì xe đạt vận tốc 12 m/s. Biết hệ số ma sát giữa xe và mặt đường là $m$= 0,04, lấy $ g = 10 m/s^{2}.$</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Áp dụng: $v^2=2as$ và định luật II Niu-tơn cho chuyển động thẳng nhanh dần đều. Đổi $m=2500$ kg.</p><p class=\"text-base leading-relaxed my-2\">$a=\\dfrac{v^2}{2s}=\\dfrac{12^2}{2\\cdot 144}=0{,}5$ m/s²</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow t=\\dfrac{v}{a}=24$ s</p><p class=\"text-base leading-relaxed my-2\">$F_{ms}=\\mu mg=0{,}04\\cdot2500\\cdot10=1000$ N</p><p class=\"text-base leading-relaxed my-2\">$F-F_{ms}=ma$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F=2500\\cdot0{,}5+1000=2250$ N</p><p class=\"text-base leading-relaxed my-2\">a) $A=Fs=2250\\cdot144=324000$ J. <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\">b) $P=\\dfrac{A}{t}=\\dfrac{324000}{24}=13500$ W $=13{,}5$ kW $\\ne 15{,}3$ kW. <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\">c) Công hao phí là công của lực ma sát: $A_{ms}=F_{ms}s=1000\\cdot144=144000$ J $\\ne104000$ J. <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\">d) Công có ích bằng động năng: $W_đ=\\dfrac12mv^2=180000$ J.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow H=\\dfrac{180000}{324000}\\approx55{,}6\\%$. <b>Đúng</b>.</p>","statements":[{"text":"Công của lực tác dụng lên xe trên quãng đường 144 m đầu tiên là 324000 J.","answer":true},{"text":"Công suất của lực do động cơ là 15,3 kW.","answer":false},{"text":"Công hao phí là 104000 J","answer":false},{"text":"Hiệu suất hoạt động của động cơ là 55,6%.","answer":true}]}$q$::jsonb, 140, $q$Tính hiệu suất của máy và động cơ$q$)) as v(q, tid, tname)
where not exists (select 1 from public.question_bank b where b.content_hash = public.question_content_hash(v.q));
